// ======================================================
// STORE GATEWAYS
// ======================================================

const component = "gateways";

try {

    // --------------------------------------------------
    // PARSEAR JSON
    // --------------------------------------------------

    const gateways = JSON.parse(msg.payload);


    // --------------------------------------------------
    // VALIDACIÓN BÁSICA
    // --------------------------------------------------

    if (
        !gateways ||
        typeof gateways !== "object" ||
        Array.isArray(gateways)
    ) {
        throw new Error(
            "gateways.json no contiene un objeto JSON válido."
        );
    }


    const gatewayIds = Object.keys(gateways);


    if (gatewayIds.length === 0) {
        throw new Error(
            "gateways.json no contiene gateways."
        );
    }


    // --------------------------------------------------
    // GUARDAR CONFIGURACIÓN
    // --------------------------------------------------

    global.set("gateways", gateways);


    // --------------------------------------------------
    // ESTADO
    // --------------------------------------------------

    node.status({
        fill: "green",
        shape: "dot",
        text: gatewayIds.length + " gateways"
    });


    // --------------------------------------------------
    // EVENTO PARA STARTUP COORDINATOR
    // --------------------------------------------------

    msg.startupEvent = {

        component: component,

        ok: true,

        count: gatewayIds.length,

        error: null,

        timestamp: new Date().toISOString()

    };


    msg.payload = gateways;

    return msg;


} catch (err) {

    // Una configuración inválida NO debe conservarse
    // como válida en memoria.

    global.set("gateways", null);


    node.status({
        fill: "red",
        shape: "ring",
        text: "ERROR"
    });


    msg.startupEvent = {

        component: component,

        ok: false,

        count: 0,

        error: err.message,

        timestamp: new Date().toISOString()

    };


    msg.payload = null;

    return msg;
}

// ======================================================
// STORE DEVICES
// ======================================================

const component = "devices";

try {

    // --------------------------------------------------
    // PARSEAR JSON
    // --------------------------------------------------

    const devices = JSON.parse(msg.payload);


    // --------------------------------------------------
    // VALIDACIÓN BÁSICA
    // --------------------------------------------------

    if (
        !devices ||
        typeof devices !== "object" ||
        Array.isArray(devices)
    ) {
        throw new Error(
            "devices.json no contiene un objeto JSON válido."
        );
    }


    const deviceIds = Object.keys(devices);


    if (deviceIds.length === 0) {
        throw new Error(
            "devices.json no contiene dispositivos."
        );
    }


    // --------------------------------------------------
    // GUARDAR CONFIGURACIÓN
    // --------------------------------------------------

    global.set("devices", devices);


    // --------------------------------------------------
    // ESTADO VISUAL
    // --------------------------------------------------

    node.status({
        fill: "green",
        shape: "dot",
        text: deviceIds.length + " devices"
    });


    // --------------------------------------------------
    // EVENTO PARA STARTUP COORDINATOR
    // --------------------------------------------------

    msg.startupEvent = {

        component: component,

        ok: true,

        count: deviceIds.length,

        error: null,

        timestamp: new Date().toISOString()

    };


    msg.payload = devices;

    return msg;


} catch (err) {

    global.set("devices", null);


    node.status({
        fill: "red",
        shape: "ring",
        text: "ERROR"
    });


    msg.startupEvent = {

        component: component,

        ok: false,

        count: 0,

        error: err.message,

        timestamp: new Date().toISOString()

    };


    msg.payload = null;

    return msg;
}

// ======================================================
// STORE DRIVERS
// ======================================================

const component = "drivers";

const fs = global.get("fs");
const path = global.get("path");


// ------------------------------------------------------
// FUNCIÓN DE ERROR
// ------------------------------------------------------

function fail(message) {

    global.set("drivers", null);

    node.status({
        fill: "red",
        shape: "ring",
        text: "ERROR"
    });

    msg.startupEvent = {

        component: component,

        ok: false,

        count: 0,

        error: message,

        timestamp: new Date().toISOString()

    };

    msg.payload = null;

    return msg;
}


// ------------------------------------------------------
// VALIDAR LIBRERÍAS
// ------------------------------------------------------

if (!fs || !path) {

    return fail(
        "fs o path no están cargados."
    );
}


// ------------------------------------------------------
// CARGAR DRIVERS
// ------------------------------------------------------

try {

    const drivers = {};

    const files = fs
        .readdirSync("/drivers")
        .filter(file => file.endsWith(".json"));


    if (files.length === 0) {

        return fail(
            "No se encontraron drivers JSON en /drivers."
        );
    }


    for (const file of files) {

        const fullPath =
            path.join("/drivers", file);

        let driver;


        try {

            const json =
                fs.readFileSync(fullPath, "utf8");

            driver = JSON.parse(json);

        } catch (err) {

            throw new Error(
                `${file}: ${err.message}`
            );
        }


        if (
            !driver ||
            typeof driver !== "object" ||
            Array.isArray(driver)
        ) {

            throw new Error(
                `${file}: el contenido no es un objeto JSON válido.`
            );
        }


        const driverId =
            path.basename(file, ".json");


        drivers[driverId] = driver;
    }


    // --------------------------------------------------
    // GUARDAR
    // --------------------------------------------------

    global.set("drivers", drivers);


    const driverIds =
        Object.keys(drivers);


    node.status({
        fill: "green",
        shape: "dot",
        text: driverIds.length + " drivers"
    });


    // --------------------------------------------------
    // EVENTO STARTUP
    // --------------------------------------------------

    msg.startupEvent = {

        component: component,

        ok: true,

        count: driverIds.length,

        error: null,

        timestamp: new Date().toISOString()

    };


    msg.payload = drivers;

    return msg;


} catch (err) {

    return fail(err.message);
}

// ======================================================
// SYSTEM STATE
// ======================================================
//
// Representa el estado GLOBAL del BMS.
//
// PRIORIDAD:
//
// 1. FAULT
// 2. READY
// 3. LOADING
//
// IMPORTANTE:
// Los mensajes mantienen msg.startup durante todo el
// recorrido del Startup.
//
// Por eso READY y FAULT deben evaluarse ANTES que
// LOADING.
// ======================================================


// ======================================================
// 1. FAULT
// ======================================================

if (
    msg.payload &&
    msg.payload.status === "FAULT"
) {

    global.set(
        "systemReady",
        false
    );


    node.status({

        fill: "red",

        shape: "dot",

        text: "FAULT"

    });


    return null;
}


// ======================================================
// 2. READY
// ======================================================

if (
    msg.validation &&
    msg.validation.ok === true
) {

    let state =
        global.get("startupState");


    if (!state) {

        global.set(
            "systemReady",
            false
        );


        node.status({

            fill: "red",

            shape: "ring",

            text: "NO STARTUP STATE"

        });


        node.error(
            "No existe startupState."
        );


        return null;
    }


    // --------------------------------------------------
    // ACTUALIZAR ESTADO
    // --------------------------------------------------

    const now =
        Date.now();


    state.status =
        "READY";


    state.readyAt =
        new Date(now).toISOString();


    const startedAt =
        Date.parse(state.startedAt);


    state.durationMs =
        Number.isFinite(startedAt)
            ? now - startedAt
            : null;


    global.set(
        "startupState",
        state
    );


    // --------------------------------------------------
    // HABILITAR SISTEMA
    // --------------------------------------------------

    global.set(
        "systemReady",
        true
    );


    // --------------------------------------------------
    // ESTADO VISUAL
    // --------------------------------------------------

    node.status({

        fill: "green",

        shape: "dot",

        text: "READY"

    });


    node.warn(
        "========== BMS READY =========="
    );


    // --------------------------------------------------
    // MENSAJE DE SALIDA
    // --------------------------------------------------

    msg.payload = {

        status: "READY",

        timestamp:
            state.readyAt,

        startupDurationMs:
            state.durationMs,

        components: {

            gateways:
                state.components.gateways.count,

            devices:
                state.components.devices.count,

            drivers:
                state.components.drivers.count

        },

        warnings:
            state.validation?.warnings || []

    };


    return msg;
}


// ======================================================
// 3. LOADING
// ======================================================

if (
    msg.startup &&
    msg.startup.action === "LOAD_ALL"
) {

    global.set(
        "systemReady",
        false
    );


    node.status({

        fill: "yellow",

        shape: "ring",

        text: "LOADING"

    });


    return null;
}


// ======================================================
// 4. MENSAJE NO RECONOCIDO
// ======================================================

node.warn(
    "System State recibió un mensaje sin estado reconocido."
);

return null;

// ======================================================
// INIT STARTUP STATE
// ======================================================
//
// Inicializa un nuevo ciclo de arranque/configuración.
//
// COMPONENTES OBLIGATORIOS:
//
// - gateways
// - devices
// - drivers
// - system
//
// OUTPUT 1:
//   Dispara la carga de configuraciones.
//
// OUTPUT 2:
//   Dispara watchdog de timeout.
//
// ======================================================


const now =
    Date.now();


const runId =
    now.toString(36) +
    "-" +
    Math.random()
        .toString(16)
        .slice(2);


// ======================================================
// ESTADO INICIAL
// ======================================================

const startupState = {

    runId:
        runId,

    status:
        "LOADING",

    startedAt:
        new Date(now).toISOString(),

    readyAt:
        null,

    durationMs:
        null,

    components: {

        gateways: {

            reported:
                false,

            ok:
                false,

            count:
                0,

            error:
                null
        },


        devices: {

            reported:
                false,

            ok:
                false,

            count:
                0,

            error:
                null
        },


        drivers: {

            reported:
                false,

            ok:
                false,

            count:
                0,

            error:
                null
        },


        system: {

            reported:
                false,

            ok:
                false,

            count:
                0,

            error:
                null
        }
    },


    validation: {

        ok:
            false,

        errors:
            [],

        warnings:
            []
    },


    errors:
        []
};


// ======================================================
// CERRAR GATE DEL SISTEMA
// ======================================================

global.set(
    "systemReady",
    false
);


global.set(
    "startupState",
    startupState
);


// ======================================================
// ESTADO VISUAL
// ======================================================

node.status({

    fill:
        "yellow",

    shape:
        "ring",

    text:
        "LOADING"

});


// ======================================================
// MENSAJE STARTUP
// ======================================================

msg.startupRunId =
    runId;


msg.startup = {

    action:
        "LOAD_ALL",

    runId:
        runId,

    timestamp:
        startupState.startedAt
};


// ======================================================
// MENSAJES INDEPENDIENTES
// ======================================================

const loadMsg =
    RED.util.cloneMessage(
        msg
    );


const timeoutMsg =
    RED.util.cloneMessage(
        msg
    );


// ======================================================
// SALIDAS
// ======================================================

return [

    loadMsg,

    timeoutMsg
];

// ======================================================
// STARTUP COORDINATOR
// ======================================================
//
// RESPONSABILIDAD:
//
// Esperar el reporte de TODOS los componentes declarados
// en startupState.components.
//
// Actualmente:
//
// - gateways
// - devices
// - drivers
// - system
//
// Ningún componente individual puede declarar
// al BMS como READY.
//
// Cuando todos los componentes cargaron correctamente:
//
//     LOADED X/X
//          ↓
//     Validate Configuration
//
// El estado READY definitivo pertenece a System State.
//
// ======================================================


const event =
    msg.startupEvent;


let state =
    global.get("startupState");


// ======================================================
// 1. VALIDAR STARTUP STATE
// ======================================================

if (!state) {

    node.status({

        fill:
            "red",

        shape:
            "ring",

        text:
            "NO STARTUP STATE"
    });


    node.warn(
        "Startup Coordinator recibió un mensaje sin startupState."
    );


    return [
        null,
        null
    ];
}


// ======================================================
// 2. VALIDAR EVENTO
// ======================================================

if (
    !event ||
    !event.component
) {

    node.warn(
        "Startup Coordinator recibió un mensaje sin startupEvent."
    );


    return [
        null,
        null
    ];
}


// ======================================================
// 3. DESCARTAR EVENTOS DE UN STARTUP ANTERIOR
// ======================================================

if (
    msg.startupRunId &&
    msg.startupRunId !== state.runId
) {

    node.warn(
        "Ignorado mensaje perteneciente a un Startup anterior."
    );


    return [
        null,
        null
    ];
}


// ======================================================
// 4. VALIDAR COMPONENTE
// ======================================================

if (
    !state.components ||
    !state.components[event.component]
) {

    node.warn(
        `Componente de Startup desconocido: ${event.component}`
    );


    return [
        null,
        null
    ];
}


// ======================================================
// 5. REGISTRAR RESULTADO DEL COMPONENTE
// ======================================================

state.components[event.component] = {

    reported:
        true,

    ok:
        event.ok === true,

    count:
        Number(
            event.count || 0
        ),

    error:
        event.error || null
};


global.set(
    "startupState",
    state
);


// ======================================================
// 6. CONTAR COMPONENTES
// ======================================================

const componentNames =
    Object.keys(
        state.components
    );


const reportedCount =
    componentNames.filter(
        name =>
            state.components[name].reported === true
    ).length;


const totalCount =
    componentNames.length;


// ======================================================
// 7. TODAVÍA ESTAMOS CARGANDO
// ======================================================

if (
    reportedCount < totalCount
) {

    node.status({

        fill:
            "yellow",

        shape:
            "ring",

        text:
            `LOADING ${reportedCount}/${totalCount}`
    });


    return [
        null,
        null
    ];
}


// ======================================================
// 8. EVITAR EJECUTAR DOS VECES
// ======================================================

if (
    state.coordinatorCompleted === true
) {

    return [
        null,
        null
    ];
}


state.coordinatorCompleted =
    true;


// ======================================================
// 9. COMPROBAR COMPONENTES FALLIDOS
// ======================================================

const failedComponents =
    componentNames.filter(
        name =>
            state.components[name].ok !== true
    );


if (
    failedComponents.length > 0
) {

    const errors =
        failedComponents.map(
            name => {

                const component =
                    state.components[name];


                return (
                    `${name}: ` +
                    (
                        component.error ||
                        "error desconocido"
                    )
                );
            }
        );


    state.status =
        "FAULT";


    state.errors =
        errors;


    global.set(
        "startupState",
        state
    );


    global.set(
        "systemReady",
        false
    );


    node.status({

        fill:
            "red",

        shape:
            "ring",

        text:
            "FAULT"
    });


    msg.payload = {

        status:
            "FAULT",

        stage:
            "LOAD",

        errors:
            errors
    };


    return [
        null,
        msg
    ];
}


// ======================================================
// 10. TODOS LOS COMPONENTES CARGADOS
// ======================================================
//
// IMPORTANTE:
//
// El Coordinator terminó correctamente.
//
// Ahora entrega el control a:
//
//     Validate Configuration
//
// Por eso su estado visual definitivo es:
//
//     LOADED X/X
//
// y NO "VALIDATING".
//
// ======================================================

state.status =
    "VALIDATING";


global.set(
    "startupState",
    state
);


node.status({

    fill:
        "green",

    shape:
        "dot",

    text:
        `LOADED ${reportedCount}/${totalCount}`
});


// ======================================================
// 11. MENSAJE HACIA VALIDATE CONFIGURATION
// ======================================================

msg.payload = {

    gateways:
        state.components.gateways?.count || 0,

    devices:
        state.components.devices?.count || 0,

    drivers:
        state.components.drivers?.count || 0,

    system:
        state.components.system?.count || 0
};


// ======================================================
// SALIDAS
// ======================================================
//
// OUTPUT 1:
//   configuración cargada correctamente
//
// OUTPUT 2:
//   error de carga
//
// ======================================================

return [
    msg,
    null
];

// ======================================================
// STARTUP TIMEOUT CHECK
// ======================================================

const state =
    global.get("startupState");


// No existe Startup activo.

if (!state) {
    return null;
}


// Este timeout pertenece a un Startup viejo.

if (
    msg.startupRunId !== state.runId
) {
    return null;
}


// El Startup ya terminó.

if (
    state.status === "READY" ||
    state.status === "FAULT"
) {
    return null;
}


// ------------------------------------------------------
// COMPONENTES QUE NO RESPONDIERON
// ------------------------------------------------------

const missing =
    Object.keys(state.components)
        .filter(
            name =>
                state.components[name].reported !== true
        );


if (missing.length === 0) {

    // Todos reportaron.
    // Si estamos acá, la validación está procesándose.
    return null;
}


// ------------------------------------------------------
// TIMEOUT
// ------------------------------------------------------

msg.payload = {

    status: "FAULT",

    stage: "TIMEOUT",

    errors: missing.map(
        name =>
            `Timeout esperando componente: ${name}`
    )

};


return msg;

// ======================================================
// VALIDATE CONFIGURATION
// ======================================================

const gateways = global.get("gateways");
const devices = global.get("devices");
const drivers = global.get("drivers");

const errors = [];
const warnings = [];


// ======================================================
// HELPERS
// ======================================================

function isObject(value) {

    return (
        value !== null &&
        typeof value === "object" &&
        !Array.isArray(value)
    );
}


function isFiniteNumber(value) {

    return Number.isFinite(
        Number(value)
    );
}


// ======================================================
// TIPOS SOPORTADOS
// ======================================================

const supportedReadTypes = new Set([

    "bool",
    "uint16",
    "int16",
    "uint32",
    "int32",
    "float",
    "bitmask"

]);


const supportedWriteTypes = new Set([

    "bool",
    "uint16",
    "int16",
    "uint32",
    "int32",
    "float"

]);


// ======================================================
// FUNCTION CODES
// ======================================================

const readFunctionCodes =
    new Set([
        1,
        2,
        3,
        4
    ]);


const writeFunctionCodes =
    new Set([
        5,
        6,
        16
    ]);


// ======================================================
// CONFIGURACIONES PRINCIPALES
// ======================================================

if (!isObject(gateways)) {

    errors.push(
        "global.gateways no es válido."
    );
}


if (!isObject(devices)) {

    errors.push(
        "global.devices no es válido."
    );
}


if (!isObject(drivers)) {

    errors.push(
        "global.drivers no es válido."
    );
}


// ======================================================
// CONTINUAR SOLO SI EXISTEN LAS ESTRUCTURAS BASE
// ======================================================

if (errors.length === 0) {


    // ==================================================
    // DEVICES
    // ==================================================

    for (
        const [deviceId, device]
        of Object.entries(devices)
    ) {

        if (!isObject(device)) {

            errors.push(
                `Device ${deviceId}: configuración inválida.`
            );

            continue;
        }


        // ----------------------------------------------
        // GATEWAY
        // ----------------------------------------------

        if (
            typeof device.gateway !== "string" ||
            device.gateway.trim() === ""
        ) {

            errors.push(
                `Device ${deviceId}: gateway inválido.`
            );

        }
        else if (
            !Object.prototype.hasOwnProperty.call(
                gateways,
                device.gateway
            )
        ) {

            errors.push(
                `Device ${deviceId}: gateway ` +
                `${device.gateway} inexistente.`
            );
        }


        // ----------------------------------------------
        // DRIVER
        // ----------------------------------------------

        if (
            typeof device.driver !== "string" ||
            device.driver.trim() === ""
        ) {

            errors.push(
                `Device ${deviceId}: driver inválido.`
            );

        }
        else if (
            !Object.prototype.hasOwnProperty.call(
                drivers,
                device.driver
            )
        ) {

            errors.push(
                `Device ${deviceId}: driver ` +
                `${device.driver} inexistente.`
            );
        }


        // ----------------------------------------------
        // MODBUS SLAVE
        // ----------------------------------------------
        //
        // Se admite 255.
        //
        // El Schneider TM221 utiliza Unit ID 255
        // para acceder a sus registros %MW.
        // ----------------------------------------------

        const slave =
            Number(device.slave);


        if (
            !Number.isInteger(slave) ||
            slave < 1 ||
            slave > 255
        ) {

            errors.push(
                `Device ${deviceId}: slave Modbus inválido ` +
                `(${device.slave}).`
            );
        }
    }


    // ==================================================
    // DRIVERS
    // ==================================================

    for (
        const [driverId, driver]
        of Object.entries(drivers)
    ) {

        if (!isObject(driver)) {

            errors.push(
                `Driver ${driverId}: configuración inválida.`
            );

            continue;
        }


        if (!isObject(driver.variables)) {

            errors.push(
                `Driver ${driverId}: no contiene variables válidas.`
            );

            continue;
        }


        const variableNames =
            Object.keys(driver.variables);


        if (variableNames.length === 0) {

            warnings.push(
                `Driver ${driverId}: no contiene variables.`
            );
        }


        // ==============================================
        // VARIABLES
        // ==============================================

        for (
            const [variableId, variable]
            of Object.entries(driver.variables)
        ) {

            if (!isObject(variable)) {

                errors.push(
                    `Driver ${driverId} / ${variableId}: ` +
                    `variable inválida.`
                );

                continue;
            }


            const readEnabled =
                variable.read === true;


            const writeEnabled =
                variable.write === true;


            // ------------------------------------------
            // Variable no utilizada
            // ------------------------------------------

            if (
                !readEnabled &&
                !writeEnabled
            ) {

                warnings.push(
                    `Driver ${driverId} / ${variableId}: ` +
                    `read y write deshabilitados.`
                );

                continue;
            }


            // ==================================================
            // TYPE GENERAL
            // ==================================================

            if (
                typeof variable.type !== "string"
            ) {

                errors.push(
                    `Driver ${driverId} / ${variableId}: ` +
                    `type no definido.`
                );

                continue;
            }


            // ==================================================
            // ADDRESS GENERAL
            // ==================================================
            //
            // address se utiliza como dirección por defecto
            // tanto para lectura como para escritura.
            //
            // Para escritura puede existir writeAddress.
            // ==================================================

            const address =
                Number(variable.address);


            if (
                !Number.isInteger(address) ||
                address < 0
            ) {

                errors.push(
                    `Driver ${driverId} / ${variableId}: ` +
                    `address inválido (${variable.address}).`
                );
            }


            // ==================================================
            // VALIDACIÓN DE LECTURA
            // ==================================================

            if (readEnabled) {


                // --------------------------------------
                // TYPE DE LECTURA
                // --------------------------------------

                if (
                    !supportedReadTypes.has(
                        variable.type
                    )
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `tipo de lectura no soportado ` +
                        `(${variable.type}).`
                    );
                }


                // --------------------------------------
                // FC DE LECTURA
                // --------------------------------------

                const fc =
                    Number(variable.fc);


                if (
                    !Number.isInteger(fc) ||
                    !readFunctionCodes.has(fc)
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `FC de lectura inválido (${variable.fc}).`
                    );
                }


                // --------------------------------------
                // QUANTITY DE LECTURA
                // --------------------------------------

                const quantity =
                    Number(variable.quantity);


                if (
                    !Number.isInteger(quantity) ||
                    quantity < 1
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `quantity inválido (${variable.quantity}).`
                    );
                }


                // --------------------------------------
                // SCAN
                // --------------------------------------

                if (
                    variable.scan !== undefined
                ) {

                    const scan =
                        Number(variable.scan);


                    if (
                        !Number.isFinite(scan) ||
                        scan < 0
                    ) {

                        errors.push(
                            `Driver ${driverId} / ${variableId}: ` +
                            `scan inválido (${variable.scan}).`
                        );
                    }
                }


                // --------------------------------------
                // BITMASK
                // --------------------------------------

                if (
                    variable.type === "bitmask"
                ) {

                    if (
                        !isObject(variable.bits)
                    ) {

                        errors.push(
                            `Driver ${driverId} / ${variableId}: ` +
                            `bitmask sin bits configurados.`
                        );

                    }
                    else {

                        for (
                            const [bitIndex, bitConfig]
                            of Object.entries(variable.bits)
                        ) {

                            const index =
                                Number(bitIndex);


                            if (
                                !Number.isInteger(index) ||
                                index < 0 ||
                                index > 15
                            ) {

                                errors.push(
                                    `Driver ${driverId} / ${variableId}: ` +
                                    `bit ${bitIndex} inválido.`
                                );
                            }


                            if (
                                !isObject(bitConfig)
                            ) {

                                errors.push(
                                    `Driver ${driverId} / ${variableId}: ` +
                                    `configuración del bit ` +
                                    `${bitIndex} inválida.`
                                );

                                continue;
                            }


                            if (
                                typeof bitConfig.point !== "string" ||
                                bitConfig.point.trim() === ""
                            ) {

                                errors.push(
                                    `Driver ${driverId} / ${variableId}: ` +
                                    `bit ${bitIndex} sin point.`
                                );
                            }


                            if (
                                typeof bitConfig.name !== "string" ||
                                bitConfig.name.trim() === ""
                            ) {

                                errors.push(
                                    `Driver ${driverId} / ${variableId}: ` +
                                    `bit ${bitIndex} sin name.`
                                );
                            }
                        }
                    }
                }
            }


            // ==================================================
            // VALIDACIÓN DE ESCRITURA
            // ==================================================

            if (writeEnabled) {


                // --------------------------------------
                // TYPE DE ESCRITURA
                // --------------------------------------

                if (
                    !supportedWriteTypes.has(
                        variable.type
                    )
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `tipo de escritura no soportado ` +
                        `(${variable.type}).`
                    );
                }


                // --------------------------------------
                // WRITE FC
                // --------------------------------------

                const writeFc =
                    Number(variable.writeFc);


                if (
                    !Number.isInteger(writeFc) ||
                    !writeFunctionCodes.has(writeFc)
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `writeFc inválido (${variable.writeFc}).`
                    );
                }


                // --------------------------------------
                // COMPATIBILIDAD TYPE ↔ FC
                // --------------------------------------

                if (
                    variable.type === "bool" &&
                    writeFc !== 5
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `BOOL requiere writeFc 5.`
                    );
                }


                if (
                    (
                        variable.type === "uint16" ||
                        variable.type === "int16"
                    ) &&
                    writeFc !== 6 &&
                    writeFc !== 16
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `${variable.type} requiere ` +
                        `writeFc 6 o 16.`
                    );
                }


                if (
                    (
                        variable.type === "uint32" ||
                        variable.type === "int32" ||
                        variable.type === "float"
                    ) &&
                    writeFc !== 16
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `${variable.type} requiere writeFc 16.`
                    );
                }


                // --------------------------------------
                // WRITE ADDRESS
                // --------------------------------------

                const writeAddress =
                    Number(
                        variable.writeAddress ??
                        variable.address
                    );


                if (
                    !Number.isInteger(writeAddress) ||
                    writeAddress < 0
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `writeAddress/address inválido ` +
                        `(${variable.writeAddress ?? variable.address}).`
                    );
                }


                // --------------------------------------
                // WRITE QUANTITY
                // --------------------------------------

                const writeQuantity =
                    Number(
                        variable.writeQuantity ??
                        variable.quantity ??
                        1
                    );


                if (
                    !Number.isInteger(writeQuantity) ||
                    writeQuantity < 1
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `writeQuantity inválido ` +
                        `(${variable.writeQuantity ?? variable.quantity}).`
                    );
                }


                // --------------------------------------
                // QUANTITY ESPERADO SEGÚN TYPE
                // --------------------------------------

                if (
                    (
                        variable.type === "bool" ||
                        variable.type === "uint16" ||
                        variable.type === "int16"
                    ) &&
                    writeQuantity !== 1
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `${variable.type} requiere ` +
                        `writeQuantity 1.`
                    );
                }


                if (
                    (
                        variable.type === "uint32" ||
                        variable.type === "int32" ||
                        variable.type === "float"
                    ) &&
                    writeQuantity !== 2
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `${variable.type} requiere ` +
                        `writeQuantity 2.`
                    );
                }


                // --------------------------------------
                // MIN
                // --------------------------------------

                if (
                    variable.min !== undefined &&
                    !isFiniteNumber(variable.min)
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `min inválido (${variable.min}).`
                    );
                }


                // --------------------------------------
                // MAX
                // --------------------------------------

                if (
                    variable.max !== undefined &&
                    !isFiniteNumber(variable.max)
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `max inválido (${variable.max}).`
                    );
                }


                // --------------------------------------
                // MIN <= MAX
                // --------------------------------------

                if (
                    variable.min !== undefined &&
                    variable.max !== undefined &&
                    isFiniteNumber(variable.min) &&
                    isFiniteNumber(variable.max) &&
                    Number(variable.min) >
                    Number(variable.max)
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `min (${variable.min}) es mayor ` +
                        `que max (${variable.max}).`
                    );
                }


                // --------------------------------------
                // MULTIPLIER PARA ESCRITURA
                // --------------------------------------
                //
                // El Writer realiza la operación inversa:
                //
                // raw = engineering / multiplier
                //
                // Por eso multiplier = 0 no es válido
                // para una variable escribible.
                // --------------------------------------

                if (
                    variable.multiplier !== undefined
                ) {

                    const multiplier =
                        Number(variable.multiplier);


                    if (
                        !Number.isFinite(multiplier) ||
                        multiplier === 0
                    ) {

                        errors.push(
                            `Driver ${driverId} / ${variableId}: ` +
                            `multiplier inválido para escritura ` +
                            `(${variable.multiplier}).`
                        );
                    }
                }
            }


            // ==================================================
            // MULTIPLIER GENERAL
            // ==================================================

            if (
                variable.multiplier !== undefined &&
                !Number.isFinite(
                    Number(variable.multiplier)
                )
            ) {

                errors.push(
                    `Driver ${driverId} / ${variableId}: ` +
                    `multiplier inválido.`
                );
            }


            // ==================================================
            // DECIMALS
            // ==================================================

            if (
                variable.decimals !== undefined
            ) {

                const decimals =
                    Number(variable.decimals);


                if (
                    !Number.isInteger(decimals) ||
                    decimals < 0
                ) {

                    errors.push(
                        `Driver ${driverId} / ${variableId}: ` +
                        `decimals inválido.`
                    );
                }
            }
        }
    }
}


// ======================================================
// ACTUALIZAR STARTUP STATE
// ======================================================

let state =
    global.get("startupState") || {};


state.validation = {

    ok:
        errors.length === 0,

    errors:
        errors,

    warnings:
        warnings

};


global.set(
    "startupState",
    state
);


// ======================================================
// RESULTADO
// ======================================================

if (
    errors.length > 0
) {

    node.status({

        fill:
            "red",

        shape:
            "ring",

        text:
            errors.length + " errores"

    });


    msg.payload = {

        status:
            "FAULT",

        stage:
            "VALIDATION",

        errors:
            errors,

        warnings:
            warnings

    };


    return [
        null,
        msg
    ];
}


// ======================================================
// VALIDACIÓN CORRECTA
// ======================================================

node.status({

    fill:
        "green",

    shape:
        "dot",

    text:
        "CONFIG OK"

});


msg.validation = {

    ok:
        true,

    warnings:
        warnings

};


return [
    msg,
    null
];

// ======================================================
// STARTUP FAULT
// ======================================================
//
// Este nodo procesa los errores del Startup.
//
// También recibe el estado READY desde System State
// únicamente para limpiar su indicador visual anterior.
//
// IMPORTANTE:
// Solo un mensaje con payload.status === "FAULT"
// puede generar una falla.
// ======================================================


// ======================================================
// 1. SISTEMA RECUPERADO / READY
// ======================================================
//
// System State envía:
//
// msg.payload.status = "READY"
//
// En este caso NO procesamos ninguna falla.
// Solamente limpiamos el indicador visual del nodo.
// ======================================================

if (
    msg.payload &&
    msg.payload.status === "READY"
) {

    node.status({});

    return null;
}


// ======================================================
// 2. IGNORAR MENSAJES QUE NO SEAN FAULT
// ======================================================

if (
    !msg.payload ||
    msg.payload.status !== "FAULT"
) {

    return null;
}


// ======================================================
// 3. PROCESAR FAULT
// ======================================================

global.set(
    "systemReady",
    false
);


let state =
    global.get("startupState") || {};


const errors =
    Array.isArray(msg.payload.errors)
        ? msg.payload.errors
        : ["Error de Startup no especificado."];


state.status =
    "FAULT";


state.failedAt =
    new Date().toISOString();


state.errors =
    errors;


global.set(
    "startupState",
    state
);


// ------------------------------------------------------
// ESTADO VISUAL
// ------------------------------------------------------

node.status({

    fill: "red",

    shape: "ring",

    text: "BMS FAULT"

});


const stage =
    msg.payload.stage || "UNKNOWN";


node.error(
    `[BMS STARTUP FAULT] ${stage}: ` +
    errors.join(" | ")
);


return msg;

// ======================================================
// STORE SYSTEM CONFIG
// ======================================================
//
// RESPONSABILIDAD:
//
// - Parsear /config/system.json
// - Validar estructura básica
// - Guardar configuración en:
//
//       global.systemConfig
//
// - Reportar resultado al Startup Coordinator
//
// ======================================================


const component =
    "system";


try {

    // ==================================================
    // 1. PARSEAR JSON
    // ==================================================

    const systemConfig =
        JSON.parse(
            msg.payload
        );


    // ==================================================
    // 2. VALIDACIÓN BASE
    // ==================================================

    if (
        !systemConfig ||
        typeof systemConfig !== "object" ||
        Array.isArray(systemConfig)
    ) {

        throw new Error(
            "system.json no contiene un objeto JSON válido."
        );
    }


    // ==================================================
    // 3. VALIDAR SCAN
    // ==================================================

    if (
        !systemConfig.scan ||
        typeof systemConfig.scan !== "object" ||
        Array.isArray(systemConfig.scan)
    ) {

        throw new Error(
            "system.json: falta configuración scan."
        );
    }


    const scanKeys = [
        "fast",
        "normal",
        "slow"
    ];


    for (
        const key
        of scanKeys
    ) {

        const value =
            Number(
                systemConfig.scan[key]
            );


        if (
            !Number.isFinite(value) ||
            value <= 0
        ) {

            throw new Error(
                `system.json: scan.${key} inválido.`
            );
        }
    }


    // ==================================================
    // 4. VALIDAR NOTIFICATIONS
    // ==================================================

    if (
        !systemConfig.notifications ||
        typeof systemConfig.notifications !== "object" ||
        Array.isArray(systemConfig.notifications)
    ) {

        throw new Error(
            "system.json: falta configuración notifications."
        );
    }


    const channels = [
        "whatsapp",
        "email",
        "telegram"
    ];


    for (
        const channel
        of channels
    ) {

        const config =
            systemConfig.notifications[channel];


        if (
            !config ||
            typeof config !== "object" ||
            Array.isArray(config)
        ) {

            throw new Error(
                `system.json: falta notifications.${channel}.`
            );
        }


        if (
            typeof config.enabled !== "boolean"
        ) {

            throw new Error(
                `system.json: notifications.${channel}.enabled ` +
                `debe ser boolean.`
            );
        }
    }


    // ==================================================
    // 5. GUARDAR CONFIGURACIÓN
    // ==================================================

    global.set(
        "systemConfig",
        systemConfig
    );


    // ==================================================
    // 6. ESTADO VISUAL
    // ==================================================

    node.status({

        fill:
            "green",

        shape:
            "dot",

        text:
            "SYSTEM CONFIG OK"

    });


    // ==================================================
    // 7. EVENTO STARTUP
    // ==================================================

    msg.startupEvent = {

        component:
            component,

        ok:
            true,

        count:
            1,

        error:
            null,

        timestamp:
            new Date().toISOString()

    };


    msg.payload =
        systemConfig;


    return msg;


}
catch (err) {


    // ==================================================
    // ERROR
    // ==================================================

    global.set(
        "systemConfig",
        null
    );


    node.status({

        fill:
            "red",

        shape:
            "ring",

        text:
            "ERROR"

    });


    msg.startupEvent = {

        component:
            component,

        ok:
            false,

        count:
            0,

        error:
            err.message,

        timestamp:
            new Date().toISOString()

    };


    msg.payload =
        null;


    return msg;
}

// ======================================================
// LOAD DEVICES
// ======================================================

// Protección adicional.
//
// Aunque alguien conecte accidentalmente otro nodo
// directamente a Load Devices, no permitimos scans
// mientras el sistema no esté READY.

if (
    global.get("systemReady") !== true
) {

    node.status({

        fill: "yellow",

        shape: "ring",

        text: "SYSTEM NOT READY"

    });

    return null;
}


// ------------------------------------------------------
// CARGAR DEVICES
// ------------------------------------------------------

const devices =
    global.get("devices");


if (
    !devices ||
    typeof devices !== "object"
) {

    node.status({

        fill: "red",

        shape: "ring",

        text: "Sin devices"

    });

    return null;
}


// ------------------------------------------------------
// LISTA DE DISPOSITIVOS
// ------------------------------------------------------

const allDeviceNames =
    Object.keys(devices);


if (allDeviceNames.length === 0) {

    node.status({

        fill: "red",

        shape: "ring",

        text: "0 devices"

    });

    return null;
}


msg.payload =
    allDeviceNames;


node.status({

    fill: "green",

    shape: "dot",

    text:
        allDeviceNames.length +
        " devices"

});


return msg;

const deviceId = msg.payload;

msg.payload = {
    action: "scan",
    deviceId: deviceId,
    timestamp: Date.now()
};

return msg;

// ======================================================
// SCHEDULER GATE
// ======================================================
//
// El reloj puede funcionar siempre.
// La adquisición solamente puede pasar cuando
// el BMS se encuentra realmente READY.
// ======================================================

const systemReady =
    global.get("systemReady") === true;


const startupState =
    global.get("startupState");


if (
    !systemReady ||
    !startupState ||
    startupState.status !== "READY"
) {

    node.status({

        fill: "yellow",

        shape: "ring",

        text: "WAITING READY"

    });

    return null;
}


// ------------------------------------------------------
// SISTEMA HABILITADO
// ------------------------------------------------------

node.status({

    fill: "green",

    shape: "dot",

    text: "RUNNING"

});


return msg;

const deviceId = msg.payload.deviceId;

const devices = global.get("devices");

if (!devices) {
    node.error("La configuración de dispositivos no está cargada.");
    return null;
}

const device = devices[deviceId];

if (!device) {
    node.error(`No existe el dispositivo ${deviceId}`);
    return null;
}

// Creamos una copia para no modificar la configuración original
msg.device = JSON.parse(JSON.stringify(device));

msg.device.id = deviceId;

return msg;

const gateways = global.get("gateways");

if (!gateways) {
    node.error("No existe gateways en memoria");
    return null;
}

const gatewayName = msg.device.gateway;

const gateway = gateways[gatewayName];

if (!gateway) {
    node.error(`Gateway ${gatewayName} inexistente`);
    return null;
}

msg.device.gateway = JSON.parse(JSON.stringify(gateway));

msg.device.gateway.id = gatewayName;

return msg;

const drivers = global.get("drivers");

if (!drivers) {
    node.error("No existen drivers cargados");
    return null;
}

const driverName = msg.device.driver;

const driver = drivers[driverName];

if (!driver) {
    node.error(`Driver ${driverName} inexistente`);
    return null;
}

msg.device.driver = JSON.parse(JSON.stringify(driver));

msg.device.driver.id = driverName;

return msg;

if (!msg.payload || !msg.payload.deviceId) {
    node.error("No llegó deviceId");
    return null;
}

return msg;

const job = msg.payload;

// Conservamos toda la información para los siguientes nodos
msg.device = job.device;
msg.point = job.point;
msg.variable = job.variable;

// Petición exactamente igual a la prueba que funciona
msg.payload = {

    fc: job.request.fc,

    unitid: job.request.unitid,

    address: job.request.address,

    quantity: job.request.quantity

};

return msg;

// ======================================================
// BUILD MEASUREMENT
// ======================================================

const deviceId =
    msg.device.id;


if (!deviceId) {

    node.error(
        "No existe device.id"
    );

    return null;
}


// ======================================================
// QUALITY DE LA MUESTRA
// ======================================================
//
// Esta quality representa el estado del device EN EL
// MOMENTO en que recibimos esta medición.
//
// La quality dinámica actual será publicada aparte por
// el Health Engine.
// ======================================================

const health =
    global.get("health") || {};


const deviceHealth =
    health.devices?.[deviceId];


const validQualities =
    new Set([
        "GOOD",
        "BAD",
        "STALE",
        "OFFLINE",
        "UNKNOWN"
    ]);


let quality =
    "UNKNOWN";


if (
    deviceHealth &&
    validQualities.has(
        deviceHealth.status
    )
) {

    quality =
        deviceHealth.status;
}


// ======================================================
// CACHE DE MEDICIONES
// ======================================================

let cache =
    flow.get("measurements") || {};


if (!cache[deviceId]) {

    cache[deviceId] = {};
}


// ======================================================
// ACTUALIZAR PUNTO
// ======================================================

cache[deviceId][msg.point] = {

    name:
        msg.variable.name,

    value:
        msg.payload.value,

    unit:
        msg.variable.unit,

    quality:
        quality,

    timestamp:
        new Date().toISOString()
};


flow.set(
    "measurements",
    cache
);


// ======================================================
// PAYLOAD DE SALIDA
// ======================================================

msg.payload = {

    deviceId:
        deviceId,

    deviceName:
        msg.device.name,

    gateway:
        msg.device.gateway.id,

    driver:
        msg.device.driver.id,

    point:
        msg.point,

    measurement:
        cache[deviceId][msg.point]

};


return msg;

const device = msg.device;

if (!device) {
    node.error("No llegó ningún dispositivo.");
    return null;
}

if (!device.driver) {
    node.error("El dispositivo no tiene driver.");
    return null;
}

const jobs = [];

// Base de tiempos de adquisición
let scanState = global.get("scanState") || {};

const now = Date.now();

for (const pointName of Object.keys(device.driver.variables)) {

    const variable = device.driver.variables[pointName];

    if (!variable) {
        node.warn(`La variable ${pointName} no existe en el driver ${device.driver.id}`);
        continue;
    }

    // Solo variables configuradas para lectura
    if (variable.read !== true) {
        continue;
    }

    // Identificador único de la variable
    const key = `${device.id}.${pointName}`;

    const lastRead = scanState[key] || 0;

    // Si no existe scan, leer siempre
    const scan = Number(variable.scan ?? 1000);

    if (scan > 0 && (now - lastRead) < scan) {
        continue;
    }

    // Actualizar instante de lectura
    scanState[key] = now;

    jobs.push({

        device: device,

        point: pointName,

        variable: variable,

        request: {

            unitid: device.slave,

            fc: variable.fc,

            address: variable.address,

            quantity: variable.quantity

        }

    });

}

global.set("scanState", scanState);

if (jobs.length === 0) {
    return null;
}

msg.payload = jobs;

return msg;

// ======================================================
// DECODE VALUE
// ======================================================
//
// RESPONSABILIDAD:
//
// 1. Decodificar la respuesta Modbus.
// 2. Aplicar multiplier / decimals.
// 3. Expandir bitmask cuando corresponda.
// 4. Generar un mensaje NORMALIZADO Y COMPACTO.
//
// MUY IMPORTANTE:
//
// A partir de este nodo NO propagamos el mensaje Modbus
// completo.
//
// Eliminamos deliberadamente:
//
// - responseBuffer
// - modbusRequest
// - parts
// - _event
// - driver completo
// - gateway completo
// - metadata interna del cliente Modbus
//
// Sólo conservamos lo necesario para:
//
// - Build Measurement
// - MQTT
// - Health
// - Alarm Engine
//
// ======================================================


// ======================================================
// HELPERS
// ======================================================

function normalizeId(value) {

    if (
        typeof value === "string"
    ) {

        return value;
    }


    if (
        value &&
        typeof value === "object" &&
        typeof value.id === "string"
    ) {

        return value.id;
    }


    return null;
}


// ------------------------------------------------------
// Copiar únicamente propiedades escalares.
//
// No copiamos objetos/arrays anidados como:
//
//     variable.bits
//
// Esto evita transportar estructuras completas del
// driver después de Decode.
// ------------------------------------------------------

function copyScalarProperties(source) {

    const result = {};


    if (
        !source ||
        typeof source !== "object"
    ) {

        return result;
    }


    for (
        const [key, value]
        of Object.entries(source)
    ) {

        if (
            value === null ||
            typeof value === "string" ||
            typeof value === "number" ||
            typeof value === "boolean"
        ) {

            result[key] =
                value;
        }
    }


    return result;
}


// ------------------------------------------------------
// Construcción del device runtime mínimo.
// ------------------------------------------------------

function buildCompactDevice() {

    const sourceDevice =
        (
            msg.device &&
            typeof msg.device === "object"
        )
            ? msg.device
            : {};


    const sourceHealth =
        (
            sourceDevice.health &&
            typeof sourceDevice.health === "object"
        )
            ? sourceDevice.health
            : {};


    const gatewayId =
        normalizeId(
            sourceDevice.gateway
        );


    const driverId =
        normalizeId(
            sourceDevice.driver
        );


    return {

        id:
            sourceDevice.id || null,

        name:
            sourceDevice.name ||
            sourceDevice.id ||
            null,

        gateway: {

            id:
                gatewayId
        },

        driver: {

            id:
                driverId
        },

        health: {

            heartbeatPoint:
                sourceHealth.heartbeatPoint ??
                null,

            heartbeatTimeoutMs:
                sourceHealth.heartbeatTimeoutMs ??
                null,

            communicationAlarmSeverity:
                sourceHealth.communicationAlarmSeverity ??
                null,

            applicationAlarmSeverity:
                sourceHealth.applicationAlarmSeverity ??
                null
        }
    };
}


// ------------------------------------------------------
// Construcción del mensaje compacto.
//
// IMPORTANTE:
//
// Creamos un objeto NUEVO.
//
// No modificamos ni devolvemos el msg Modbus original.
// ------------------------------------------------------

function buildCompactMessage(
    point,
    variableData,
    decodedValue
) {

    const compactMsg = {

        _msgid:
            msg._msgid,

        point:
            point,

        device:
            buildCompactDevice(),

        variable:
            variableData,

        payload: {

            value:
                decodedValue
        }
    };


    // Conservamos topic únicamente si ya existe
    // y es un string pequeño.

    if (
        typeof msg.topic === "string"
    ) {

        compactMsg.topic =
            msg.topic;
    }


    return compactMsg;
}


// ======================================================
// VALIDACIONES
// ======================================================

const regs =
    msg.payload;


if (
    !Array.isArray(regs)
) {

    return null;
}


const variable =
    msg.variable;


if (
    !variable ||
    typeof variable !== "object"
) {

    node.error(
        "Decode Value: falta msg.variable"
    );

    return null;
}


// ======================================================
// DECODIFICACIÓN
// ======================================================

let value;


switch (
    variable.type
) {

    // ==================================================
    // BOOL
    // ==================================================

    case "bool":

        value =
            regs[0]
                ? 1
                : 0;

        break;


    // ==================================================
    // UINT16
    // ==================================================

    case "uint16":

        value =
            regs[0];

        break;


    // ==================================================
    // INT16
    // ==================================================

    case "int16": {

        const buffer =
            Buffer.alloc(2);


        buffer.writeUInt16BE(
            regs[0],
            0
        );


        value =
            buffer.readInt16BE(0);

        break;
    }


    // ==================================================
    // UINT32
    // ==================================================

    case "uint32": {

        const r0 =
            regs[0];

        const r1 =
            regs[1];


        if (
            variable.swap
        ) {

            value =
                ((r0 << 16) >>> 0) +
                r1;

        } else {

            value =
                ((r1 << 16) >>> 0) +
                r0;
        }


        break;
    }


    // ==================================================
    // INT32
    // ==================================================

    case "int32": {

        const buffer =
            Buffer.alloc(4);


        if (
            variable.swap
        ) {

            buffer.writeUInt16BE(
                regs[1],
                0
            );

            buffer.writeUInt16BE(
                regs[0],
                2
            );

        } else {

            buffer.writeUInt16BE(
                regs[0],
                0
            );

            buffer.writeUInt16BE(
                regs[1],
                2
            );
        }


        value =
            buffer.readInt32BE(0);

        break;
    }


    // ==================================================
    // FLOAT
    // ==================================================

    case "float": {

        const buffer =
            Buffer.alloc(4);


        if (
            variable.swap
        ) {

            buffer.writeUInt16BE(
                regs[1],
                0
            );

            buffer.writeUInt16BE(
                regs[0],
                2
            );

        } else {

            buffer.writeUInt16BE(
                regs[0],
                0
            );

            buffer.writeUInt16BE(
                regs[1],
                2
            );
        }


        value =
            buffer.readFloatBE(0);

        break;
    }


    // ==================================================
    // BITMASK
    // ==================================================

    case "bitmask": {

        const wordValue =
            regs[0];


        if (
            wordValue === undefined
        ) {

            node.error(
                "Bitmask: no se recibieron datos en regs[0]"
            );

            return null;
        }


        if (
            !variable.bits ||
            typeof variable.bits !== "object"
        ) {

            node.error(
                "Tipo bitmask seleccionado pero no existen bits definidos."
            );

            return null;
        }


        // ----------------------------------------------
        // Config base compacta de la variable.
        // ----------------------------------------------

        const baseVariable =
            copyScalarProperties(
                variable
            );


        // ----------------------------------------------
        // Generar un mensaje pequeño por cada bit.
        //
        // IMPORTANTE:
        //
        // YA NO usamos:
        //
        //     RED.util.cloneMessage(msg)
        //
        // Nunca clonamos el mensaje Modbus completo.
        // ----------------------------------------------

        for (
            const [bitIndex, bitConfigRaw]
            of Object.entries(variable.bits)
        ) {

            const index =
                Number.parseInt(
                    bitIndex,
                    10
                );


            if (
                !Number.isInteger(index)
            ) {

                continue;
            }


            const bitConfig =
                (
                    bitConfigRaw &&
                    typeof bitConfigRaw === "object"
                )
                    ? bitConfigRaw
                    : {};


            const point =
                bitConfig.point;


            if (
                typeof point !== "string" ||
                point.trim() === ""
            ) {

                node.warn(
                    `Bitmask: bit ${bitIndex} sin point`
                );

                continue;
            }


            const bitValue =
                (
                    (
                        wordValue >>
                        index
                    ) &
                    1
                ) === 1
                    ? 1
                    : 0;


            // ------------------------------------------
            // Variable compacta específica del bit.
            // ------------------------------------------

            const bitVariable = {

                ...baseVariable,

                ...copyScalarProperties(
                    bitConfig
                ),

                name:
                    bitConfig.name ||
                    baseVariable.name ||
                    point,

                type:
                    "bool"
            };


            // ------------------------------------------
            // Mensaje compacto.
            // ------------------------------------------

            const outputMsg =
                buildCompactMessage(
                    point,
                    bitVariable,
                    bitValue
                );


            node.send(
                outputMsg
            );
        }


        // El mensaje bitmask original no continúa.

        return null;
    }


    // ==================================================
    // DESCONOCIDO
    // ==================================================

    default:

        node.error(
            `Tipo desconocido: ${variable.type}`
        );

        return null;
}


// ======================================================
// POST-PROCESADO
// ======================================================

if (
    typeof value === "number"
) {

    if (
        variable.multiplier !== undefined
    ) {

        value *=
            variable.multiplier;
    }


    if (
        variable.decimals !== undefined
    ) {

        value =
            Number(
                value.toFixed(
                    variable.decimals
                )
            );
    }
}


// ======================================================
// VARIABLE COMPACTA
// ======================================================

const compactVariable =
    copyScalarProperties(
        variable
    );


// ======================================================
// SALIDA NORMALIZADA
// ======================================================

return buildCompactMessage(
    msg.point,
    compactVariable,
    value
);

// ======================================================
// MARK COMMUNICATION OK
// ======================================================
//
// RESPONSABILIDAD:
//
// Una respuesta Modbus válida constituye evidencia de
// comunicación correcta con:
//
// - el DEVICE
// - el camino a través del GATEWAY
//
// IMPORTANTE:
//
// Este nodo YA NO escribe global.health.
//
// Solamente actualiza:
//
//     global.communicationState
//
// El único nodo que construye y escribe global.health
// será Health Watchdog.
//
// El mensaje continúa SIN MODIFICACIONES hacia Decode.
// ======================================================


// ------------------------------------------------------
// VALIDAR DEVICE
// ------------------------------------------------------

if (
    !msg.device ||
    !msg.device.id
) {

    node.warn(
        "Mark Communication OK: falta msg.device.id"
    );

    return msg;
}


// ------------------------------------------------------
// VALIDAR GATEWAY
// ------------------------------------------------------

if (
    !msg.device.gateway ||
    !msg.device.gateway.id
) {

    node.warn(
        `Mark Communication OK: ${msg.device.id} sin gateway`
    );

    return msg;
}


// ======================================================
// IDENTIFICACIÓN
// ======================================================

const deviceId =
    msg.device.id;

const gatewayId =
    msg.device.gateway.id;

const now =
    Date.now();

const nowIso =
    new Date(now).toISOString();


// ======================================================
// ESTADO ACTUAL
// ======================================================

const currentState =
    global.get("communicationState") || {};


const currentDevices =
    (
        currentState.devices &&
        typeof currentState.devices === "object"
    )
        ? currentState.devices
        : {};


const currentGateways =
    (
        currentState.gateways &&
        typeof currentState.gateways === "object"
    )
        ? currentState.gateways
        : {};


// ======================================================
// DEVICE COMMUNICATION STATE
// ======================================================
//
// Creamos un objeto NUEVO.
// No modificamos directamente el objeto recuperado
// del contexto.
// ======================================================

const previousDevice =
    currentDevices[deviceId] || {};


const nextDevice = {

    ...previousDevice,

    id:
        deviceId,

    name:
        msg.device.name || deviceId,

    gateway:
        gatewayId,

    driver:
        msg.device.driver?.id || null,

    lastSeen:
        now,

    lastSeenIso:
        nowIso
};


// ======================================================
// GATEWAY COMMUNICATION STATE
// ======================================================

const previousGateway =
    currentGateways[gatewayId] || {};


const nextGateway = {

    ...previousGateway,

    id:
        gatewayId,

    lastSeen:
        now,

    lastSeenIso:
        nowIso
};


// ======================================================
// CONSTRUIR NUEVO communicationState
// ======================================================

const nextState = {

    devices: {

        ...currentDevices,

        [deviceId]:
            nextDevice
    },

    gateways: {

        ...currentGateways,

        [gatewayId]:
            nextGateway
    },

    updatedAt:
        nowIso
};


// ======================================================
// GUARDAR RAW COMMUNICATION STATE
// ======================================================

global.set(
    "communicationState",
    nextState
);


// ======================================================
// STATUS VISUAL
// ======================================================

node.status({

    fill:
        "green",

    shape:
        "dot",

    text:
        `${gatewayId} / ${deviceId}`
});


// ======================================================
// CONTINUAR ADQUISICIÓN
// ======================================================

return msg;

// ======================================================
// HEALTH MESSAGE PROJECTOR
// + HEARTBEAT FILTER
// ======================================================
//
// RESPONSABILIDAD:
//
// Crear la frontera entre Acquisition y Health.
//
// Este nodo:
//
// 1. recibe el mensaje compacto desde Decode Value
// 2. verifica si el device tiene heartbeat configurado
// 3. deja pasar ÚNICAMENTE el punto heartbeat
// 4. genera un mensaje mínimo para Heart Observer
//
// De esta manera:
//
// - Health NO recibe todas las mediciones
// - eliminamos el Heart Bit Filter separado
// - sólo circula 1 mensaje cuando realmente se lee
//   el heartbeat configurado
//
// ======================================================


// ======================================================
// 1. VALIDAR DEVICE
// ======================================================

if (
    !msg ||
    !msg.device ||
    !msg.device.id
) {

    return null;
}


// ======================================================
// 2. HEALTH CONFIG
// ======================================================

const sourceHealth =
    (
        msg.device.health &&
        typeof msg.device.health === "object"
    )
        ? msg.device.health
        : null;


if (
    !sourceHealth
) {

    return null;
}


// ======================================================
// 3. HEARTBEAT CONFIGURADO
// ======================================================

const heartbeatPoint =
    sourceHealth.heartbeatPoint;


if (
    typeof heartbeatPoint !== "string" ||
    heartbeatPoint.trim() === ""
) {

    return null;
}


// ======================================================
// 4. FILTRO HEARTBEAT
// ======================================================
//
// Sólo dejamos pasar:
//
//     msg.point === heartbeatPoint
//
// Todas las demás variables mueren aquí.
//
// ======================================================

if (
    msg.point !== heartbeatPoint
) {

    return null;
}


// ======================================================
// 5. VALIDAR VALOR
// ======================================================

const value =
    msg.payload?.value;


if (
    value === undefined ||
    value === null
) {

    return null;
}


// ======================================================
// 6. MENSAJE HEALTH MÍNIMO
// ======================================================
//
// Creamos un objeto NUEVO.
//
// No reenviamos:
// - variable
// - driver
// - gateway
// - Modbus metadata
// - buffers
// - configuración completa
//
// ======================================================

return {

    _msgid:
        msg._msgid,

    point:
        heartbeatPoint,

    payload: {

        value:
            value
    },

    device: {

        id:
            msg.device.id,

        name:
            msg.device.name ||
            msg.device.id,

        health: {

            heartbeatPoint:
                heartbeatPoint,

            heartbeatTimeoutMs:
                sourceHealth.heartbeatTimeoutMs ??
                null
        }
    }
};

// ======================================================
// HEARTBEAT OBSERVER
// ======================================================
//
// RESPONSABILIDAD:
//
// Observar exclusivamente el heartbeat configurado
// para cada device.
//
// Mantiene estado crudo de heartbeat en:
//
//     global.heartbeatState
//
// REGISTRA:
//
// - último valor
// - última lectura
// - último cambio
//
// IMPORTANTE:
//
// Este nodo YA NO:
//
// - modifica global.health
// - decide BAD
// - decide GOOD global
// - decide OFFLINE
//
// Todo eso corresponde a Health Watchdog.
//
// Health Watchdog será el único escritor de:
//
//     global.health
// ======================================================


// ------------------------------------------------------
// VALIDAR DEVICE
// ------------------------------------------------------

if (
    !msg.device ||
    !msg.device.id
) {

    return null;
}


const deviceId =
    msg.device.id;


// ======================================================
// HEARTBEAT CONFIGURADO
// ======================================================

const heartbeatPoint =
    msg.device.health?.heartbeatPoint;


if (
    typeof heartbeatPoint !== "string" ||
    heartbeatPoint.trim() === ""
) {

    return null;
}


// ======================================================
// ¿ES ESTE MENSAJE EL HEARTBEAT?
// ======================================================

if (
    msg.point !== heartbeatPoint
) {

    return null;
}


// ======================================================
// VALOR
// ======================================================

const value =
    msg.payload?.value;


if (
    value === undefined ||
    value === null
) {

    node.warn(
        `Heartbeat ${deviceId}: valor inválido`
    );

    return null;
}


// ======================================================
// TIEMPO
// ======================================================

const now =
    Date.now();

const nowIso =
    new Date(now).toISOString();


// ======================================================
// ESTADO ACTUAL
// ======================================================

const currentState =
    global.get("heartbeatState") || {};


const currentDevices =
    (
        currentState.devices &&
        typeof currentState.devices === "object"
    )
        ? currentState.devices
        : {};


const previous =
    currentDevices[deviceId] || {};


// ======================================================
// DETECTAR CAMBIO
// ======================================================

const firstReading =
    previous.lastValue === undefined;


const changed =
    firstReading ||
    value !== previous.lastValue;


// ======================================================
// LAST CHANGE
// ======================================================

const lastChange =
    changed
        ? now
        : previous.lastChange;


const lastChangeIso =
    changed
        ? nowIso
        : previous.lastChangeIso;


// ======================================================
// NUEVO ESTADO DEL DEVICE
// ======================================================

const nextDevice = {

    id:
        deviceId,

    heartbeatPoint:
        heartbeatPoint,

    lastSeen:
        now,

    lastSeenIso:
        nowIso,

    lastValue:
        value,

    lastChange:
        lastChange,

    lastChangeIso:
        lastChangeIso
};


// ======================================================
// CONSTRUIR NUEVO heartbeatState
// ======================================================
//
// No mutamos directamente el objeto obtenido del
// contexto.
//
// Creamos una nueva estructura pequeña.
// ======================================================

const nextState = {

    devices: {

        ...currentDevices,

        [deviceId]:
            nextDevice
    },

    updatedAt:
        nowIso
};


// ======================================================
// GUARDAR
// ======================================================

global.set(
    "heartbeatState",
    nextState
);


// ======================================================
// STATUS
// ======================================================

node.status({

    fill:
        "green",

    shape:
        "dot",

    text:
        `${deviceId}: HB ${value}`
});


return null;

// ======================================================
// HEALTH WATCHDOG
// ======================================================
//
// RESPONSABILIDAD:
//
// Ser el ÚNICO propietario/escritor de:
//
//     global.health
//
// FUENTES:
//
//     global.communicationState
//     global.heartbeatState
//     global.devices
//     global.gateways
//
// Además implementa REARME DE HEARTBEAT:
//
// Cuando un device recupera comunicación:
//
//     OFFLINE/STALE/UNKNOWN -> GOOD
//
// NO se evalúa inmediatamente el heartbeat histórico.
//
// Se espera:
//
// - un nuevo cambio real de heartbeat
//
// o
//
// - que venza heartbeatTimeoutMs
//
// Esto evita alarmas falsas de aplicación inmediatamente
// después de recuperar comunicación.
//
// ======================================================


// ======================================================
// HELPERS
// ======================================================

function normalizeId(value) {

    if (
        typeof value === "string"
    ) {

        return value;
    }


    if (
        value &&
        typeof value === "object" &&
        typeof value.id === "string"
    ) {

        return value.id;
    }


    return null;
}


function validTimestamp(value) {

    return (
        typeof value === "number" &&
        Number.isFinite(value) &&
        value > 0
    );
}


// ======================================================
// TIEMPO
// ======================================================

const now =
    Date.now();


const nowIso =
    new Date(now).toISOString();


// ======================================================
// CONFIGURACIÓN
// ======================================================

const configuredDevices =
    global.get("devices") || {};


const configuredGateways =
    global.get("gateways") || {};


// ======================================================
// ESTADOS CRUDOS
// ======================================================

const communicationState =
    global.get("communicationState") || {};


const communicationDevices =
    (
        communicationState.devices &&
        typeof communicationState.devices === "object"
    )
        ? communicationState.devices
        : {};


const communicationGateways =
    (
        communicationState.gateways &&
        typeof communicationState.gateways === "object"
    )
        ? communicationState.gateways
        : {};


const heartbeatState =
    global.get("heartbeatState") || {};


const heartbeatDevices =
    (
        heartbeatState.devices &&
        typeof heartbeatState.devices === "object"
    )
        ? heartbeatState.devices
        : {};


// ======================================================
// HEALTH ANTERIOR
// ======================================================

const previousHealth =
    global.get("health") || {};


const previousDevices =
    (
        previousHealth.devices &&
        typeof previousHealth.devices === "object"
    )
        ? previousHealth.devices
        : {};


const previousGateways =
    (
        previousHealth.gateways &&
        typeof previousHealth.gateways === "object"
    )
        ? previousHealth.gateways
        : {};


// ======================================================
// NUEVO SNAPSHOT
// ======================================================

const nextHealth = {

    devices:
        {},

    gateways:
        {},

    summary:
        {},

    updatedAt:
        nowIso
};


// ======================================================
// 1. GATEWAYS
// ======================================================

for (
    const [gatewayId, gatewayConfig]
    of Object.entries(configuredGateways)
) {

    const previous =
        previousGateways[gatewayId] || {};


    const raw =
        communicationGateways[gatewayId] || {};


    // --------------------------------------------------
    // MONITORING SINCE
    // --------------------------------------------------

    const monitoringSince =
        validTimestamp(
            previous.monitoringSince
        )
            ? previous.monitoringSince
            : now;


    const monitoringSinceIso =
        previous.monitoringSinceIso ||
        new Date(
            monitoringSince
        ).toISOString();


    // --------------------------------------------------
    // TIMEOUTS
    // --------------------------------------------------

    const configuredStale =
        Number(
            gatewayConfig.health?.staleAfterMs
        );


    const configuredOffline =
        Number(
            gatewayConfig.health?.offlineAfterMs
        );


    const staleAfterMs =
        (
            Number.isFinite(configuredStale) &&
            configuredStale > 0
        )
            ? configuredStale
            : 5000;


    const offlineAfterMs =
        (
            Number.isFinite(configuredOffline) &&
            configuredOffline > staleAfterMs
        )
            ? configuredOffline
            : 15000;


    // --------------------------------------------------
    // LAST SEEN
    // --------------------------------------------------

    const lastSeen =
        validTimestamp(
            raw.lastSeen
        )
            ? raw.lastSeen
            : null;


    const lastSeenIso =
        lastSeen
            ? (
                raw.lastSeenIso ||
                new Date(
                    lastSeen
                ).toISOString()
            )
            : null;


    // --------------------------------------------------
    // AGE
    // --------------------------------------------------

    const ageMs =
        lastSeen
            ? now - lastSeen
            : now - monitoringSince;


    // --------------------------------------------------
    // STATUS
    // --------------------------------------------------

    let status;


    if (
        ageMs >= offlineAfterMs
    ) {

        status =
            "OFFLINE";

    } else if (
        ageMs >= staleAfterMs
    ) {

        status =
            "STALE";

    } else if (
        lastSeen
    ) {

        status =
            "GOOD";

    } else {

        status =
            "UNKNOWN";
    }


    // --------------------------------------------------
    // SNAPSHOT
    // --------------------------------------------------

    nextHealth.gateways[gatewayId] = {

        id:
            gatewayId,

        status:
            status,

        lastSeen:
            lastSeen,

        lastSeenIso:
            lastSeenIso,

        monitoringSince:
            monitoringSince,

        monitoringSinceIso:
            monitoringSinceIso,

        staleAfterMs:
            staleAfterMs,

        offlineAfterMs:
            offlineAfterMs,

        ageMs:
            ageMs
    };
}


// ======================================================
// 2. DEVICES
// ======================================================

for (
    const [deviceId, deviceConfig]
    of Object.entries(configuredDevices)
) {

    const previous =
        previousDevices[deviceId] || {};


    const rawCommunication =
        communicationDevices[deviceId] || {};


    const rawHeartbeat =
        heartbeatDevices[deviceId] || {};


    // ==================================================
    // METADATA
    // ==================================================

    const gatewayId =
        normalizeId(
            deviceConfig.gateway
        );


    const driverId =
        normalizeId(
            deviceConfig.driver
        );


    const monitoringSince =
        validTimestamp(
            previous.monitoringSince
        )
            ? previous.monitoringSince
            : now;


    const monitoringSinceIso =
        previous.monitoringSinceIso ||
        new Date(
            monitoringSince
        ).toISOString();


    // ==================================================
    // ALARM CONFIG
    // ==================================================

    const communicationAlarmSeverity =
        (
            typeof
                deviceConfig.health
                    ?.communicationAlarmSeverity
                === "string" &&
            deviceConfig.health
                .communicationAlarmSeverity
                .trim() !== ""
        )
            ? deviceConfig.health
                .communicationAlarmSeverity
            : "WARNING";


    const applicationAlarmSeverity =
        (
            typeof
                deviceConfig.health
                    ?.applicationAlarmSeverity
                === "string" &&
            deviceConfig.health
                .applicationAlarmSeverity
                .trim() !== ""
        )
            ? deviceConfig.health
                .applicationAlarmSeverity
            : "CRITICAL";


    const alarmConfig = {

        communicationSeverity:
            communicationAlarmSeverity,

        applicationSeverity:
            applicationAlarmSeverity
    };


    // ==================================================
    // COMMUNICATION CONFIG
    // ==================================================

    const configuredStale =
        Number(
            deviceConfig.health?.staleAfterMs
        );


    const configuredOffline =
        Number(
            deviceConfig.health?.offlineAfterMs
        );


    const staleAfterMs =
        (
            Number.isFinite(configuredStale) &&
            configuredStale > 0
        )
            ? configuredStale
            : 5000;


    const offlineAfterMs =
        (
            Number.isFinite(configuredOffline) &&
            configuredOffline > staleAfterMs
        )
            ? configuredOffline
            : 15000;


    // ==================================================
    // COMMUNICATION LAST SEEN
    // ==================================================

    const communicationLastSeen =
        validTimestamp(
            rawCommunication.lastSeen
        )
            ? rawCommunication.lastSeen
            : null;


    const communicationLastSeenIso =
        communicationLastSeen
            ? (
                rawCommunication.lastSeenIso ||
                new Date(
                    communicationLastSeen
                ).toISOString()
            )
            : null;


    const communicationAge =
        communicationLastSeen
            ? now - communicationLastSeen
            : now - monitoringSince;


    // ==================================================
    // COMMUNICATION STATUS
    // ==================================================

    let communicationStatus;


    if (
        communicationAge >=
        offlineAfterMs
    ) {

        communicationStatus =
            "OFFLINE";

    } else if (
        communicationAge >=
        staleAfterMs
    ) {

        communicationStatus =
            "STALE";

    } else if (
        communicationLastSeen
    ) {

        communicationStatus =
            "GOOD";

    } else {

        communicationStatus =
            "UNKNOWN";
    }


    const previousCommunicationStatus =
        previous.communication?.status ||
        "UNKNOWN";


    const communicationRecovered =
        (
            communicationStatus === "GOOD" &&
            previousCommunicationStatus !== "GOOD"
        );


    const communication = {

        status:
            communicationStatus,

        lastSeen:
            communicationLastSeen,

        lastSeenIso:
            communicationLastSeenIso,

        staleAfterMs:
            staleAfterMs,

        offlineAfterMs:
            offlineAfterMs,

        ageMs:
            communicationAge
    };


    // ==================================================
    // HEARTBEAT CONFIG
    // ==================================================

    const heartbeatPoint =
        deviceConfig.health?.heartbeatPoint;


    const heartbeatEnabled =
        (
            typeof heartbeatPoint === "string" &&
            heartbeatPoint.trim() !== ""
        );


    const configuredHeartbeatTimeout =
        Number(
            deviceConfig.health?.heartbeatTimeoutMs
        );


    const heartbeatTimeoutMs =
        (
            Number.isFinite(
                configuredHeartbeatTimeout
            ) &&
            configuredHeartbeatTimeout > 0
        )
            ? configuredHeartbeatTimeout
            : 5000;


    // ==================================================
    // APPLICATION BASE
    // ==================================================

    const previousApplication =
        previous.application || {};


    const applicationMonitoringSince =
        heartbeatEnabled
            ? (
                validTimestamp(
                    previousApplication.monitoringSince
                )
                    ? previousApplication.monitoringSince
                    : now
            )
            : null;


    const applicationMonitoringSinceIso =
        heartbeatEnabled
            ? (
                previousApplication.monitoringSinceIso ||
                new Date(
                    applicationMonitoringSince
                ).toISOString()
            )
            : null;


    const application = {

        enabled:
            heartbeatEnabled,

        heartbeatPoint:
            heartbeatEnabled
                ? heartbeatPoint
                : null,

        timeoutMs:
            heartbeatTimeoutMs
    };


    if (
        heartbeatEnabled
    ) {

        application.monitoringSince =
            applicationMonitoringSince;


        application.monitoringSinceIso =
            applicationMonitoringSinceIso;


        application.lastSeen =
            validTimestamp(
                rawHeartbeat.lastSeen
            )
                ? rawHeartbeat.lastSeen
                : null;


        application.lastSeenIso =
            application.lastSeen
                ? rawHeartbeat.lastSeenIso || null
                : null;


        application.lastValue =
            rawHeartbeat.lastValue;


        application.lastChange =
            validTimestamp(
                rawHeartbeat.lastChange
            )
                ? rawHeartbeat.lastChange
                : null;


        application.lastChangeIso =
            application.lastChange
                ? rawHeartbeat.lastChangeIso || null
                : null;
    }


    // ==================================================
    // HEARTBEAT REARM
    // ==================================================
    //
    // Cuando la comunicación recupera GOOD:
    //
    //     guardamos recoverySince = now
    //
    // Hasta recibir un NUEVO cambio de heartbeat:
    //
    //     application = UNKNOWN
    //
    // Si no aparece un nuevo cambio dentro de
    // heartbeatTimeoutMs:
    //
    //     application = BAD
    //
    // ==================================================

    let recoverySince =
        validTimestamp(
            previousApplication.recoverySince
        )
            ? previousApplication.recoverySince
            : null;


    let recoverySinceIso =
        recoverySince
            ? (
                previousApplication.recoverySinceIso ||
                new Date(
                    recoverySince
                ).toISOString()
            )
            : null;


    if (
        heartbeatEnabled !== true ||
        communicationStatus !== "GOOD"
    ) {

        recoverySince =
            null;

        recoverySinceIso =
            null;

    } else if (
        communicationRecovered
    ) {

        recoverySince =
            now;

        recoverySinceIso =
            nowIso;
    }


    // ==================================================
    // APPLICATION STATUS
    // ==================================================

    if (
        heartbeatEnabled !== true
    ) {

        application.status =
            "NOT_MONIT";


    } else if (
        communication.status !== "GOOD"
    ) {

        application.status =
            "UNKNOWN";


    } else if (
        recoverySince
    ) {

        // ----------------------------------------------
        // Estamos esperando una evidencia NUEVA de que
        // la aplicación está ejecutándose.
        // ----------------------------------------------

        const heartbeatChangedAfterRecovery =
            (
                validTimestamp(
                    application.lastChange
                ) &&
                application.lastChange >
                    recoverySince
            );


        if (
            heartbeatChangedAfterRecovery
        ) {

            // Heartbeat confirmado.
            //
            // Salimos inmediatamente del período
            // de rearme.

            recoverySince =
                null;

            recoverySinceIso =
                null;

            application.status =
                "GOOD";

            application.ageSinceChangeMs =
                now -
                application.lastChange;

        } else {

            const recoveryAge =
                now -
                recoverySince;


            application.recoveryAgeMs =
                recoveryAge;


            if (
                recoveryAge >=
                heartbeatTimeoutMs
            ) {

                application.status =
                    "BAD";

            } else {

                application.status =
                    "UNKNOWN";
            }
        }


    } else if (
        application.lastChange
    ) {

        const heartbeatAge =
            now -
            application.lastChange;


        application.ageSinceChangeMs =
            heartbeatAge;


        if (
            heartbeatAge >=
            heartbeatTimeoutMs
        ) {

            application.status =
                "BAD";

        } else {

            application.status =
                "GOOD";
        }


    } else {

        const monitoringAge =
            now -
            applicationMonitoringSince;


        application.ageSinceChangeMs =
            monitoringAge;


        if (
            monitoringAge >=
            heartbeatTimeoutMs
        ) {

            application.status =
                "BAD";

        } else {

            application.status =
                "UNKNOWN";
        }
    }


    // ==================================================
    // GUARDAR ESTADO DE REARME
    // ==================================================

    if (
        recoverySince
    ) {

        application.recoverySince =
            recoverySince;

        application.recoverySinceIso =
            recoverySinceIso;
    }


    // ==================================================
    // DEVICE GLOBAL STATUS
    // ==================================================

    let deviceStatus;


    if (
        communication.status === "OFFLINE"
    ) {

        deviceStatus =
            "OFFLINE";

    } else if (
        communication.status === "STALE"
    ) {

        deviceStatus =
            "STALE";

    } else if (
        communication.status === "UNKNOWN"
    ) {

        deviceStatus =
            "UNKNOWN";

    } else if (
        application.enabled === true &&
        application.status === "BAD"
    ) {

        deviceStatus =
            "BAD";

    } else if (
        application.enabled === true &&
        application.status === "UNKNOWN"
    ) {

        deviceStatus =
            "UNKNOWN";

    } else {

        deviceStatus =
            "GOOD";
    }


    // ==================================================
    // DEVICE SNAPSHOT
    // ==================================================

    nextHealth.devices[deviceId] = {

        id:
            deviceId,

        name:
            deviceConfig.name ||
            deviceId,

        gateway:
            gatewayId,

        driver:
            driverId,

        status:
            deviceStatus,

        monitoringSince:
            monitoringSince,

        monitoringSinceIso:
            monitoringSinceIso,

        alarmConfig:
            alarmConfig,

        communication:
            communication,

        application:
            application
    };
}


// ======================================================
// 3. SUMMARY
// ======================================================

const allDevices =
    Object.values(
        nextHealth.devices
    );


const summary = {

    total:
        allDevices.length,

    good:
        allDevices.filter(
            device =>
                device.status === "GOOD"
        ).length,

    bad:
        allDevices.filter(
            device =>
                device.status === "BAD"
        ).length,

    stale:
        allDevices.filter(
            device =>
                device.status === "STALE"
        ).length,

    offline:
        allDevices.filter(
            device =>
                device.status === "OFFLINE"
        ).length,

    unknown:
        allDevices.filter(
            device =>
                device.status === "UNKNOWN"
        ).length
};


nextHealth.summary =
    summary;


nextHealth.updatedAt =
    nowIso;


// ======================================================
// 4. ÚNICA ESCRITURA DE global.health
// ======================================================

global.set(
    "health",
    nextHealth
);


// ======================================================
// 5. STATUS
// ======================================================

node.status({

    fill:
        (
            summary.bad === 0 &&
            summary.stale === 0 &&
            summary.offline === 0 &&
            summary.unknown === 0
        )
            ? "green"
            : "yellow",

    shape:
        "dot",

    text:
        `G:${summary.good} ` +
        `B:${summary.bad} ` +
        `S:${summary.stale} ` +
        `O:${summary.offline}`
});


// ======================================================
// 6. SALIDA MÍNIMA
// ======================================================

return {

    _msgid:
        msg._msgid,

    payload: {

        type:
            "healthTick",

        timestamp:
            nowIso
    }
};

// ======================================================
// HEALTH MQTT PUBLISHER
// ======================================================
//
// Convierte global.health a topics MQTT simples,
// ideales para FUXA.
//
// Publica únicamente cuando cambia un valor.
//
// Los mensajes serán retained.
//
// ======================================================


const health =
    msg.health ||
    global.get("health") ||
    {};


const summary =
    health.summary ||
    msg.healthSummary ||
    {};


const startupState =
    global.get("startupState") || {};


const systemReady =
    global.get("systemReady") === true;


// ======================================================
// CACHE DE ÚLTIMOS VALORES PUBLICADOS
// ======================================================

let published =
    context.get("published") || {};


// ======================================================
// HELPER
// ======================================================

function publish(
    topic,
    payload
) {

    const serialized =
        JSON.stringify(payload);


    if (
        published[topic] === serialized
    ) {

        return;
    }


    published[topic] =
        serialized;


    node.send({

        topic:
            topic,

        payload:
            payload,

        qos:
            0,

        retain:
            true

    });
}


// ======================================================
// CÓDIGOS DE ESTADO
// ======================================================
//
// 0 = UNKNOWN
// 1 = GOOD
// 2 = BAD
// 3 = STALE
// 4 = OFFLINE
// 5 = NOT_MONITORED
//
// Estos códigos son útiles para FUXA,
// especialmente para colores/animaciones.
// ======================================================

function healthCode(status) {

    switch (status) {

        case "GOOD":
            return 1;

        case "BAD":
            return 2;

        case "STALE":
            return 3;

        case "OFFLINE":
            return 4;

        case "NOT_MONIT":
            return 5;

        case "UNKNOWN":
        default:
            return 0;
    }
}


// ======================================================
// SYSTEM STATUS
// ======================================================

let systemStatus =
    startupState.status || "UNKNOWN";


if (
    systemReady === true
) {

    systemStatus =
        "READY";
}


function systemCode(status) {

    switch (status) {

        case "READY":
            return 1;

        case "LOADING":
        case "VALIDATING":
            return 2;

        case "FAULT":
            return 3;

        default:
            return 0;
    }
}


publish(
    "bms/health/system/status",
    systemStatus
);


publish(
    "bms/health/system/code",
    systemCode(systemStatus)
);


// ======================================================
// SUMMARY
// ======================================================

publish(
    "bms/health/summary/total",
    Number(summary.total || 0)
);


publish(
    "bms/health/summary/good",
    Number(summary.good || 0)
);


publish(
    "bms/health/summary/bad",
    Number(summary.bad || 0)
);


publish(
    "bms/health/summary/stale",
    Number(summary.stale || 0)
);


publish(
    "bms/health/summary/offline",
    Number(summary.offline || 0)
);


publish(
    "bms/health/summary/unknown",
    Number(summary.unknown || 0)
);


// ======================================================
// GATEWAYS
// ======================================================

for (
    const [gatewayId, gateway]
    of Object.entries(
        health.gateways || {}
    )
) {

    const status =
        gateway.status || "UNKNOWN";


    publish(
        `bms/health/gateways/${gatewayId}/status`,
        status
    );


    publish(
        `bms/health/gateways/${gatewayId}/code`,
        healthCode(status)
    );
}


// ======================================================
// DEVICES
// ======================================================

for (
    const [deviceId, device]
    of Object.entries(
        health.devices || {}
    )
) {

    const deviceStatus =
        device.status || "UNKNOWN";


    const communicationStatus =
        device.communication?.status ||
        "UNKNOWN";


    const applicationEnabled =
        device.application?.enabled === true;


    const applicationStatus =
        applicationEnabled

            ? (
                device.application?.status ||
                "UNKNOWN"
            )

            : "NOT_MONIT";


    // --------------------------------------------------
    // DEVICE GLOBAL
    // --------------------------------------------------

    publish(
        `bms/health/devices/${deviceId}/status`,
        deviceStatus
    );


    publish(
        `bms/health/devices/${deviceId}/code`,
        healthCode(deviceStatus)
    );


    // --------------------------------------------------
    // COMMUNICATION
    // --------------------------------------------------

    publish(
        `bms/health/devices/${deviceId}/communication/status`,
        communicationStatus
    );


    publish(
        `bms/health/devices/${deviceId}/communication/code`,
        healthCode(
            communicationStatus
        )
    );


    // --------------------------------------------------
    // APPLICATION
    // --------------------------------------------------

    publish(
        `bms/health/devices/${deviceId}/application/enabled`,
        applicationEnabled
            ? 1
            : 0
    );


    publish(
        `bms/health/devices/${deviceId}/application/status`,
        applicationStatus
    );


    publish(
        `bms/health/devices/${deviceId}/application/code`,
        healthCode(
            applicationStatus
        )
    );
}


// ======================================================
// GUARDAR CACHE
// ======================================================

context.set(
    "published",
    published
);


// ======================================================
// STATUS
// ======================================================

node.status({

    fill:
        "green",

    shape:
        "dot",

    text:
        "MQTT Health OK"
});


return null;

// ======================================================
// QUALITY MQTT PUBLISHER
// ======================================================
//
// Publica la QUALITY ACTUAL de cada punto configurado.
//
// La quality deriva del estado global del device.
//
// Ejemplo:
//
// bms/HAIWELL/AIRMED/MedicalAirTankPressure/quality
// GOOD
//
// bms/HAIWELL/AIRMED/MedicalAirTankPressure/qualityCode
// 1
//
// Solo publica cuando cambia.
//
// Mensajes retained.
// ======================================================


// ======================================================
// CONFIGURACIÓN
// ======================================================

const devices =
    global.get("devices") || {};


const drivers =
    global.get("drivers") || {};


const health =
    global.get("health") || {};


// ======================================================
// CACHE DE PUBLICACIÓN
// ======================================================

let published =
    context.get("published") || {};


// ======================================================
// QUALITY CODE
// ======================================================

function qualityCode(status) {

    switch (status) {

        case "GOOD":
            return 1;

        case "BAD":
            return 2;

        case "STALE":
            return 3;

        case "OFFLINE":
            return 4;

        case "UNKNOWN":
        default:
            return 0;
    }
}


// ======================================================
// PUBLICAR SOLO SI CAMBIÓ
// ======================================================

function publish(
    topic,
    payload
) {

    const serialized =
        JSON.stringify(payload);


    if (
        published[topic] === serialized
    ) {

        return;
    }


    published[topic] =
        serialized;


    node.send({

        topic:
            topic,

        payload:
            payload,

        qos:
            0,

        retain:
            true
    });
}


// ======================================================
// DEVICES
// ======================================================

for (
    const [deviceId, deviceConfig]
    of Object.entries(devices)
) {

    const gatewayId =
        deviceConfig.gateway;


    const driverId =
        deviceConfig.driver;


    const driver =
        drivers[driverId];


    if (
        !gatewayId ||
        !driver ||
        !driver.variables
    ) {

        continue;
    }


    // --------------------------------------------------
    // QUALITY DEL DEVICE
    // --------------------------------------------------

    const deviceHealth =
        health.devices?.[deviceId];


    const quality =
        deviceHealth?.status ||
        "UNKNOWN";


    const code =
        qualityCode(
            quality
        );


    // ==================================================
    // VARIABLES DEL DRIVER
    // ==================================================

    for (
        const [variableId, variable]
        of Object.entries(driver.variables)
    ) {

        if (
            !variable ||
            variable.read !== true
        ) {

            continue;
        }


        // =================================================
        // BITMASK
        // =================================================
        //
        // El punto real publicado no es el nombre del
        // registro base sino cada bitConfig.point.
        // =================================================

        if (
            variable.type === "bitmask" &&
            variable.bits &&
            typeof variable.bits === "object"
        ) {

            for (
                const bitConfig
                of Object.values(variable.bits)
            ) {

                if (
                    !bitConfig ||
                    typeof bitConfig.point !== "string"
                ) {

                    continue;
                }


                const pointId =
                    bitConfig.point;


                publish(

                    `bms/${gatewayId}/${deviceId}/${pointId}/quality`,

                    quality
                );


                publish(

                    `bms/${gatewayId}/${deviceId}/${pointId}/qualityCode`,

                    code
                );
            }


            continue;
        }


        // =================================================
        // VARIABLE NORMAL
        // =================================================

        const pointId =
            variableId;


        publish(

            `bms/${gatewayId}/${deviceId}/${pointId}/quality`,

            quality
        );


        publish(

            `bms/${gatewayId}/${deviceId}/${pointId}/qualityCode`,

            code
        );
    }
}


// ======================================================
// GUARDAR CACHE
// ======================================================

context.set(
    "published",
    published
);


// ======================================================
// STATUS
// ======================================================

node.status({

    fill:
        "green",

    shape:
        "dot",

    text:
        "QUALITY MQTT OK"
});


return null;

// ======================================================
// HEALTH ALARM ADAPTER
// ======================================================
//
// RESPONSABILIDAD:
//
// Convertir los estados normalizados de global.health
// al formato binario utilizado por Alarm Engine.
//
// IMPORTANTE:
//
// Los IDs técnicos permanecen estables:
//
//     BMS_Communication
//     BMS_ApplicationHeartbeat
//
// Los nombres y descripciones enviados al usuario
// utilizan lenguaje simple y comprensible.
//
// FUNCIONAMIENTO:
//
// CHANGE-ONLY.
//
// Sólo emite cuando cambia el estado binario.
//
// ======================================================


// ======================================================
// 1. HEALTH RUNTIME
// ======================================================

const health =
    global.get("health") || {};


const healthDevices =
    (
        health.devices &&
        typeof health.devices === "object"
    )
        ? health.devices
        : {};


// ======================================================
// 2. CACHE CHANGE-ONLY
// ======================================================

let lastStates =
    global.get(
        "healthAlarmAdapterState"
    );


if (
    !lastStates ||
    typeof lastStates !== "object" ||
    Array.isArray(lastStates)
) {

    lastStates = {};
}


let cacheChanged =
    false;


// ======================================================
// 3. RECORRER DEVICES
// ======================================================

for (
    const [deviceId, deviceHealth]
    of Object.entries(healthDevices)
) {

    if (
        !deviceHealth ||
        typeof deviceHealth !== "object"
    ) {

        continue;
    }


    // ==================================================
    // METADATA
    // ==================================================

    const deviceName =
        deviceHealth.name ||
        deviceId;


    const gatewayId =
        deviceHealth.gateway ||
        null;


    const alarmConfig =
        deviceHealth.alarmConfig || {};


    const communicationSeverity =
        alarmConfig.communicationSeverity ||
        "WARNING";


    const applicationSeverity =
        alarmConfig.applicationSeverity ||
        "CRITICAL";


    // ==================================================
    // 4. COMUNICACIÓN
    // ==================================================

    const communicationStatus =
        deviceHealth.communication?.status ||
        "UNKNOWN";


    let communicationValue =
        null;


    if (
        communicationStatus === "GOOD"
    ) {

        communicationValue =
            0;

    }
    else if (
        communicationStatus === "OFFLINE"
    ) {

        communicationValue =
            1;
    }


    if (
        communicationValue !== null
    ) {

        const stateKey =
            `${deviceId}.BMS_Communication`;


        const hasPrevious =
            Object.prototype.hasOwnProperty.call(
                lastStates,
                stateKey
            );


        const changed =
            !hasPrevious ||
            lastStates[stateKey] !==
                communicationValue;


        if (
            changed
        ) {

            lastStates[stateKey] =
                communicationValue;


            cacheChanged =
                true;


            node.send({

                healthAlarm:
                    true,

                device: {

                    id:
                        deviceId,

                    name:
                        deviceName,

                    gateway:
                        gatewayId
                },

                point:
                    "BMS_Communication",

                variable: {

                    name:
                        "Equipo sin comunicación",

                    type:
                        "bool",

                    unit:
                        "",

                    alarm:
                        true,

                    severity:
                        communicationSeverity,

                    message:
                        "Supervisión de la comunicación entre el BMS y el equipo."
                },

                payload: {

                    value:
                        communicationValue
                }
            });
        }
    }


    // ==================================================
    // 5. APLICACIÓN / HEARTBEAT
    // ==================================================

    const application =
        deviceHealth.application || {};


    if (
        application.enabled !== true
    ) {

        continue;
    }


    const applicationStatus =
        application.status ||
        "UNKNOWN";


    let applicationValue =
        null;


    if (
        applicationStatus === "GOOD"
    ) {

        applicationValue =
            0;

    }
    else if (
        applicationStatus === "BAD"
    ) {

        applicationValue =
            1;
    }


    if (
        applicationValue !== null
    ) {

        const stateKey =
            `${deviceId}.BMS_ApplicationHeartbeat`;


        const hasPrevious =
            Object.prototype.hasOwnProperty.call(
                lastStates,
                stateKey
            );


        const changed =
            !hasPrevious ||
            lastStates[stateKey] !==
                applicationValue;


        if (
            changed
        ) {

            lastStates[stateKey] =
                applicationValue;


            cacheChanged =
                true;


            node.send({

                healthAlarm:
                    true,

                device: {

                    id:
                        deviceId,

                    name:
                        deviceName,

                    gateway:
                        gatewayId
                },

                point:
                    "BMS_ApplicationHeartbeat",

                variable: {

                    name:
                        "Aplicación no responde",

                    type:
                        "bool",

                    unit:
                        "",

                    alarm:
                        true,

                    severity:
                        applicationSeverity,

                    message:
                        "Supervisión de ejecución del programa en tiempo real."
                },

                payload: {

                    value:
                        applicationValue
                }
            });
        }
    }
}


// ======================================================
// 6. GUARDAR CACHE SÓLO SI CAMBIÓ
// ======================================================

if (
    cacheChanged
) {

    global.set(
        "healthAlarmAdapterState",
        lastStates
    );
}


// ======================================================
// FIN
// ======================================================

return null;

// ======================================================
// HEART MESSAGE INSPECT ONCE
// ======================================================
//
// DIAGNÓSTICO TEMPORAL.
//
// OBJETIVO:
//
// Inspeccionar UN SOLO mensaje real que sale del
// Heart Bit Filter.
//
// Queremos conocer:
//
// - propiedades top-level de msg
// - tipo de cada propiedad
// - tamaño JSON aproximado
// - estructura de device
// - tamaño de device
// - estructura y tamaño de driver
// - cantidad de variables del driver
// - tamaño de variable
// - presencia de request, parts, _event, etc.
//
// IMPORTANTE:
//
// Esta Function NO modifica el mensaje.
// NO lo reenvía.
// Después de capturar la primera muestra queda muda.
//
// NO ES CÓDIGO DEFINITIVO DEL CORE.
// ======================================================


// ------------------------------------------------------
// EJECUTAR UNA SOLA VEZ
// ------------------------------------------------------

if (context.get("inspectionDone") === true) {
    return null;
}

context.set("inspectionDone", true);


// ======================================================
// HELPERS
// ======================================================

function getType(value) {

    if (value === null) {
        return "null";
    }

    if (Buffer.isBuffer(value)) {
        return "Buffer";
    }

    if (Array.isArray(value)) {
        return "Array";
    }

    return typeof value;
}


function safeJsonBytes(value) {

    const seen =
        new WeakSet();

    try {

        const json =
            JSON.stringify(
                value,
                function (key, currentValue) {

                    // ----------------------------------
                    // BigInt
                    // ----------------------------------

                    if (
                        typeof currentValue === "bigint"
                    ) {

                        return (
                            currentValue.toString() +
                            "n"
                        );
                    }


                    // ----------------------------------
                    // Buffer
                    // ----------------------------------

                    if (
                        Buffer.isBuffer(currentValue)
                    ) {

                        return (
                            `[Buffer ${currentValue.length} bytes]`
                        );
                    }


                    // ----------------------------------
                    // Buffer convertido por toJSON()
                    // ----------------------------------

                    if (
                        currentValue &&
                        typeof currentValue === "object" &&
                        currentValue.type === "Buffer" &&
                        Array.isArray(currentValue.data)
                    ) {

                        return (
                            `[Buffer ${currentValue.data.length} bytes]`
                        );
                    }


                    // ----------------------------------
                    // REFERENCIAS CIRCULARES
                    // ----------------------------------

                    if (
                        currentValue &&
                        typeof currentValue === "object"
                    ) {

                        if (
                            seen.has(currentValue)
                        ) {

                            return "[Circular]";
                        }

                        seen.add(currentValue);
                    }


                    return currentValue;
                }
            );


        if (
            json === undefined
        ) {

            return null;
        }


        return Buffer.byteLength(
            json,
            "utf8"
        );

    } catch (err) {

        return (
            "ERROR: " +
            err.message
        );
    }
}


function summarizeProperty(
    name,
    value
) {

    const summary = {

        type:
            getType(value),

        jsonBytes:
            safeJsonBytes(value)
    };


    // --------------------------------------------------
    // ARRAY
    // --------------------------------------------------

    if (
        Array.isArray(value)
    ) {

        summary.length =
            value.length;
    }


    // --------------------------------------------------
    // BUFFER
    // --------------------------------------------------

    if (
        Buffer.isBuffer(value)
    ) {

        summary.bufferBytes =
            value.length;
    }


    // --------------------------------------------------
    // OBJECT
    // --------------------------------------------------

    if (
        value &&
        typeof value === "object" &&
        !Array.isArray(value) &&
        !Buffer.isBuffer(value)
    ) {

        summary.keys =
            Object.keys(value).slice(
                0,
                50
            );

        summary.keyCount =
            Object.keys(value).length;
    }


    // --------------------------------------------------
    // STRING
    // --------------------------------------------------

    if (
        typeof value === "string"
    ) {

        summary.stringLength =
            value.length;
    }


    return summary;
}


// ======================================================
// RESULTADO GENERAL
// ======================================================

const report = {

    timestamp:
        new Date().toISOString(),

    msgid:
        msg._msgid || null,

    point:
        msg.point || null,

    topLevelKeyCount:
        Object.keys(msg).length,

    topLevelKeys:
        Object.keys(msg),

    estimatedTotalJsonBytes:
        safeJsonBytes(msg),

    properties: {}
};


// ======================================================
// INSPECCIONAR TODAS LAS PROPIEDADES TOP LEVEL
// ======================================================

for (
    const key of Object.keys(msg)
) {

    report.properties[key] =
        summarizeProperty(
            key,
            msg[key]
        );
}


// ======================================================
// DEVICE
// ======================================================

if (
    msg.device &&
    typeof msg.device === "object"
) {

    report.device = {

        id:
            msg.device.id || null,

        keys:
            Object.keys(msg.device),

        keyCount:
            Object.keys(msg.device).length,

        estimatedJsonBytes:
            safeJsonBytes(
                msg.device
            )
    };


    // ==================================================
    // DEVICE.DRIVER
    // ==================================================

    if (
        msg.device.driver &&
        typeof msg.device.driver === "object"
    ) {

        const driver =
            msg.device.driver;

        const variables =
            driver.variables;


        report.device.driver = {

            id:
                driver.id || null,

            keys:
                Object.keys(driver),

            estimatedJsonBytes:
                safeJsonBytes(
                    driver
                ),

            variablesCount:
                (
                    variables &&
                    typeof variables === "object"
                )
                    ? Object.keys(
                        variables
                    ).length
                    : 0,

            variablesEstimatedJsonBytes:
                (
                    variables &&
                    typeof variables === "object"
                )
                    ? safeJsonBytes(
                        variables
                    )
                    : null
        };
    }


    // ==================================================
    // DEVICE.GATEWAY
    // ==================================================

    if (
        msg.device.gateway &&
        typeof msg.device.gateway === "object"
    ) {

        report.device.gateway = {

            id:
                msg.device.gateway.id || null,

            keys:
                Object.keys(
                    msg.device.gateway
                ),

            estimatedJsonBytes:
                safeJsonBytes(
                    msg.device.gateway
                )
        };
    }
}


// ======================================================
// VARIABLE
// ======================================================

if (
    msg.variable &&
    typeof msg.variable === "object"
) {

    report.variable = {

        keys:
            Object.keys(
                msg.variable
            ),

        estimatedJsonBytes:
            safeJsonBytes(
                msg.variable
            )
    };
}


// ======================================================
// RELACIONES / REFERENCIAS
// ======================================================

report.referenceChecks = {

    variableIsDriverVariable:
        Boolean(
            msg.device &&
            msg.device.driver &&
            msg.device.driver.variables &&
            msg.point &&
            msg.variable ===
                msg.device.driver.variables[msg.point]
        ),

    deviceDriverIsMsgDriver:
        Boolean(
            msg.driver &&
            msg.device &&
            msg.device.driver &&
            msg.driver ===
                msg.device.driver
        )
};


// ======================================================
// IMPRIMIR
// ======================================================

node.warn(
    "\n" +
    "========== HEART MESSAGE INSPECTION ==========\n" +
    JSON.stringify(
        report,
        null,
        2
    ) +
    "\n" +
    "==============================================="
);


// ======================================================
// NO REENVIAR
// ======================================================

return null;

// ======================================================
// MQTT FORMATTER
// ======================================================

const data =
    msg.payload;


// ------------------------------------------------------
// VALIDACIÓN
// ------------------------------------------------------

if (
    !data ||
    !data.measurement
) {

    return null;
}


// ------------------------------------------------------
// DATOS
// ------------------------------------------------------

const gateway =
    data.gateway;

const deviceId =
    data.deviceId;

const pointName =
    data.point;

const m =
    data.measurement;


// ======================================================
// PUBLICACIÓN DEL VALOR
// ======================================================
//
// IMPORTANTE:
//
// Seguimos enviando SOLAMENTE el valor escalar como
// payload MQTT para mantener compatibilidad con FUXA.
//
// La quality dinámica se publica desde Health Engine.
// ======================================================

node.send({

    _msgid:
        msg._msgid,

    topic:
        `bms/${gateway}/${deviceId}/${pointName}`,

    payload:
        m.value,

    metadata: {

        gateway:
            gateway,

        deviceId:
            deviceId,

        point:
            pointName,

        name:
            m.name,

        unit:
            m.unit,

        quality:
            m.quality || "UNKNOWN",

        timestamp:
            m.timestamp
    }
});


// ======================================================
// STATUS
// ======================================================

node.status({

    fill:
        "green",

    shape:
        "dot",

    text:
        `${pointName}: ${m.value} ${m.unit || ""}`
});


return null;

const data = msg.payload;

const gateway = data.gateway;
const deviceId = data.deviceId;

for (const pointName in data.measurements) {

    const m = data.measurements[pointName];

    node.send({

        _msgid: msg._msgid,

        topic: `bms/${gateway}/${deviceId}/${pointName}`,

        payload: m.value,

        metadata: {
            gateway,
            deviceId,
            point: pointName,
            name: m.name,
            unit: m.unit,
            quality: m.quality || "GOOD",
            timestamp: m.timestamp
        }

    });

}

return null;

const req = msg.payload;

// Verificar que llegó un objeto
if (!req || typeof req !== "object") {
    node.error("El comando recibido no es un objeto");
    return null;
}

// Convertir y validar parámetros
const fc = parseInt(req.fc);
const address = parseInt(req.address);
const quantity = parseInt(req.quantity);
const unitid = parseInt(req.unitid);
const gateway = parseInt(req.gateway);

if (isNaN(fc)) {
    node.error("FC inválido");
    return null;
}

if (isNaN(address)) {
    node.error("Address inválido");
    return null;
}

if (isNaN(quantity)) {
    node.error("Quantity inválido");
    return null;
}

if (isNaN(unitid)) {
    node.error("Unit ID inválido");
    return null;
}

if (isNaN(gateway)) {
    node.error("Gateway inválido");
    return null;
}

// Construir comando limpio
msg.payload = {
    fc: fc,
    address: address,
    quantity: quantity,
    unitid: unitid,
    gateway: gateway
};

return msg;

const req = msg.payload;

msg.payload = {
    fc: req.fc,
    unitid: req.unitid,
    address: req.address,
    quantity: req.quantity
};

return msg;

const result = msg.payload;

const mensajes = [];

// ======================================================
// RECORRER TODOS LOS RESULTADOS
// ======================================================

for (const tipo in result) {

    mensajes.push({

        topic: "bms/diagnostico/resultado/" + tipo,

        payload: result[tipo]

    });
}

// Enviar todos los mensajes por la salida 1

return [mensajes];

const req = msg.payload;

msg.payload = {
    fc: req.fc,
    unitid: req.unitid,
    address: req.address,
    quantity: req.quantity
};

return msg;

const req = msg.payload;

msg.payload = {
    fc: req.fc,
    unitid: req.unitid,
    address: req.address,
    quantity: req.quantity
};

return msg;

// ======================================================
// DIAGNOSTIC COMMAND SAFETY GUARD
// ======================================================
//
// Protege el canal:
//
//     bms/diagnostico/comando
//
// contra comandos MQTT retained.
//
// SALIDA 1:
//     Comando NUEVO autorizado.
//
// SALIDA 2:
//     Tombstone MQTT para eliminar el retained.
//
// POLÍTICA:
//
// - retained histórico:
//       NO ejecutar
//       eliminar del broker
//
// - comando nuevo:
//       ejecutar una vez
//       eliminar cualquier retained inmediatamente
//
// - tombstone:
//       ignorar
//
// ======================================================


// ======================================================
// 1. VALIDAR TOPIC
// ======================================================

const expectedTopic =
    "bms/diagnostico/comando";


if (
    typeof msg.topic !== "string" ||
    msg.topic !== expectedTopic
) {

    node.error(
        "Diagnostic Command Safety Guard: topic inválido: " +
        msg.topic
    );

    return [
        null,
        null
    ];
}


// ======================================================
// 2. DETECTAR PAYLOAD VACÍO
// ======================================================

let emptyPayload = false;


if (
    msg.payload === null ||
    msg.payload === undefined
) {

    emptyPayload = true;

}
else if (
    Buffer.isBuffer(msg.payload)
) {

    emptyPayload =
        msg.payload.length === 0;

}
else if (
    typeof msg.payload === "string"
) {

    emptyPayload =
        msg.payload.length === 0;
}


// ======================================================
// TOMBSTONE
// ======================================================
//
// El mensaje utilizado para borrar el retained
// también puede volver a entrar por la suscripción.
//
// Se ignora completamente.
// ======================================================

if (emptyPayload) {

    node.status({

        fill: "grey",

        shape: "ring",

        text: "TOMBSTONE"

    });


    return [
        null,
        null
    ];
}


// ======================================================
// 3. PREPARAR LIMPIEZA
// ======================================================

const clearMsg = {

    topic:
        expectedTopic,

    payload:
        "",

    qos:
        0,

    retain:
        true,

    commandCleanup:
        true,

    timestamp:
        Date.now()

};


// ======================================================
// 4. RETAINED HISTÓRICO
// ======================================================

if (
    msg.retain === true
) {

    node.status({

        fill: "yellow",

        shape: "ring",

        text: "RETAINED BLOCKED"

    });


    node.warn(
        "MQTT DIAGNOSTIC COMMAND BLOCKED - retained histórico"
    );


    return [

        null,

        clearMsg

    ];
}


// ======================================================
// 5. COMANDO NUEVO
// ======================================================

node.status({

    fill: "green",

    shape: "dot",

    text: "COMMAND ACCEPTED"

});


return [

    msg,

    clearMsg

];

// Topic esperado:
// bms/<gateway>/<device>/<variable>/write

const parts = msg.topic.split("/");

if (parts.length !== 5) {
    node.error("Topic MQTT inválido: " + msg.topic);
    return null;
}

if (
    parts[0] !== "bms" ||
    parts[4] !== "write"
) {
    node.error("Topic no corresponde a una escritura: " + msg.topic);
    return null;
}

const gatewayId = parts[1];
const deviceId = parts[2];
const variableName = parts[3];

// Convertimos el payload a texto
let value = String(msg.payload).trim();

//--------------------------------------
// BOOL
//--------------------------------------

if (value.toLowerCase() === "true") {
    value = true;
}
else if (value.toLowerCase() === "false") {
    value = false;
}

//--------------------------------------
// NUMBER
//--------------------------------------

else if (value !== "" && !isNaN(value)) {
    value = Number(value);
}

//--------------------------------------
// Validación
//--------------------------------------

if (value === "") {
    node.error("No se recibió ningún valor.");
    return null;
}

msg.writeRequest = {

    gateway: gatewayId,

    device: deviceId,

    variable: variableName,

    value: value

};

return msg;

const deviceId = msg.writeRequest.device;

const devices = global.get("devices");

if (!devices) {
    node.error("No existe devices en memoria.");
    return null;
}

const device = devices[deviceId];

if (!device) {
    node.error(`No existe el dispositivo ${deviceId}.`);
    return null;
}

// Copia para no modificar la configuración original
msg.device = JSON.parse(JSON.stringify(device));

msg.device.id = deviceId;

return msg;

const gateways = global.get("gateways");

if (!gateways) {
    node.error("No existen gateways en memoria.");
    return null;
}

const gatewayId = msg.writeRequest.gateway;

const gateway = gateways[gatewayId];

if (!gateway) {
    node.error(`No existe el gateway ${gatewayId}.`);
    return null;
}

msg.gateway = JSON.parse(JSON.stringify(gateway));

msg.gateway.id = gatewayId;

return msg;

const drivers = global.get("drivers");

if (!drivers) {
    node.error("No existen drivers en memoria.");
    return null;
}

const driverName = msg.device.driver;

const driver = drivers[driverName];

if (!driver) {
    node.error(`No existe el driver ${driverName}.`);
    return null;
}

msg.device.driver = JSON.parse(JSON.stringify(driver));

msg.device.driver.id = driverName;

return msg;

const variableName = msg.writeRequest.variable;

if (!msg.device || !msg.device.driver) {
    node.error("No existe driver en msg.device.");
    return null;
}

const variables = msg.device.driver.variables;

if (!variables) {
    node.error(
        `El driver ${msg.device.driver.id} no tiene variables.`
    );
    return null;
}

const variable = variables[variableName];

if (!variable) {
    node.error(
        `La variable ${variableName} no existe en el driver ${msg.device.driver.id}.`
    );
    return null;
}

msg.variable = variable;
msg.point = variableName;

return msg;

// ======================================================
// VALIDATE WRITE
// ======================================================
//
// Valida una solicitud de escritura.
//
// Convención del driver:
//
//     fc       = Function Code de LECTURA
//     writeFc  = Function Code de ESCRITURA
//
// Ejemplo:
//
//     fc: 3
//     writeFc: 6
//
// ======================================================


// ======================================================
// 1. VALIDACIONES BÁSICAS
// ======================================================

if (
    !msg.writeRequest ||
    typeof msg.writeRequest !== "object"
) {

    node.error(
        "Validate Write: falta msg.writeRequest"
    );

    return null;
}


if (
    !msg.device ||
    typeof msg.device !== "object"
) {

    node.error(
        "Validate Write: falta msg.device"
    );

    return null;
}


if (
    !msg.gateway ||
    typeof msg.gateway !== "object"
) {

    node.error(
        "Validate Write: falta msg.gateway"
    );

    return null;
}


if (
    !msg.variable ||
    typeof msg.variable !== "object"
) {

    node.error(
        "Validate Write: falta msg.variable"
    );

    return null;
}


// ======================================================
// 2. CONSISTENCIA DEVICE ↔ GATEWAY
// ======================================================

let deviceGatewayId = null;


if (
    typeof msg.device.gateway === "string"
) {

    deviceGatewayId =
        msg.device.gateway;

}
else if (
    msg.device.gateway &&
    typeof msg.device.gateway === "object"
) {

    deviceGatewayId =
        msg.device.gateway.id || null;
}


const requestedGatewayId =
    msg.writeRequest.gateway;


if (!deviceGatewayId) {

    node.error(
        `Validate Write: el device ${msg.device.id} ` +
        `no tiene gateway válido.`
    );

    return null;
}


if (
    requestedGatewayId !== deviceGatewayId
) {

    node.error(
        `Validate Write: gateway inválido para ${msg.device.id}. ` +
        `Solicitado=${requestedGatewayId}, ` +
        `Configurado=${deviceGatewayId}`
    );

    return null;
}


// ======================================================
// 3. VARIABLE HABILITADA PARA ESCRITURA
// ======================================================

if (
    msg.variable.write !== true
) {

    node.error(
        `Validate Write: la variable ${msg.point} ` +
        `no está habilitada para escritura.`
    );

    return null;
}


// ======================================================
// 4. TYPE
// ======================================================

const type =
    msg.variable.type;


const supportedTypes = [
    "bool",
    "uint16",
    "int16",
    "uint32",
    "int32",
    "float"
];


if (
    typeof type !== "string" ||
    !supportedTypes.includes(type)
) {

    node.error(
        `Validate Write: tipo de escritura no soportado ` +
        `para ${msg.point}: ${type}`
    );

    return null;
}


// ======================================================
// 5. ADDRESS
// ======================================================

const address =
    Number(
        msg.variable.writeAddress ??
        msg.variable.address
    );


if (
    !Number.isInteger(address) ||
    address < 0
) {

    node.error(
        `Validate Write: address inválido para ${msg.point}.`
    );

    return null;
}


// ======================================================
// 6. FUNCTION CODE DE ESCRITURA
// ======================================================

const writeFc =
    Number(
        msg.variable.writeFc
    );


const allowedWriteFc = [
    5,
    6,
    15,
    16
];


if (
    !Number.isInteger(writeFc) ||
    !allowedWriteFc.includes(writeFc)
) {

    node.error(
        `Validate Write: writeFc inválido para ` +
        `${msg.point}: ${msg.variable.writeFc}`
    );

    return null;
}


// ======================================================
// 7. QUANTITY
// ======================================================

let quantity =
    Number(
        msg.variable.writeQuantity ??
        msg.variable.quantity
    );


if (
    !Number.isInteger(quantity) ||
    quantity <= 0
) {

    quantity = 1;
}


// ======================================================
// 8. UNIT ID
// ======================================================

const unitid =
    Number(
        msg.device.slave
    );


if (
    !Number.isInteger(unitid) ||
    unitid < 1 ||
    unitid > 255
) {

    node.error(
        `Validate Write: slave/unitid inválido ` +
        `para ${msg.device.id}.`
    );

    return null;
}


// ======================================================
// 9. VALUE
// ======================================================

const rawValue =
    msg.writeRequest.value;


if (
    rawValue === undefined ||
    rawValue === null ||
    rawValue === ""
) {

    node.error(
        `Validate Write: no se recibió value ` +
        `para ${msg.point}.`
    );

    return null;
}


// ======================================================
// 10. BOOL
// ======================================================

if (
    type === "bool"
) {

    const normalized =
        typeof rawValue === "string"
            ? rawValue.toLowerCase()
            : rawValue;


    const validBool =
        normalized === true ||
        normalized === false ||
        normalized === 1 ||
        normalized === 0 ||
        normalized === "1" ||
        normalized === "0" ||
        normalized === "true" ||
        normalized === "false";


    if (!validBool) {

        node.error(
            `Validate Write: valor BOOL inválido ` +
            `para ${msg.point}: ${rawValue}`
        );

        return null;
    }
}


// ======================================================
// 11. NUMÉRICOS
// ======================================================

else {

    const numericValue =
        Number(rawValue);


    if (
        !Number.isFinite(numericValue)
    ) {

        node.error(
            `Validate Write: valor numérico inválido ` +
            `para ${msg.point}: ${rawValue}`
        );

        return null;
    }


    const ranges = {

        uint16: {
            min: 0,
            max: 65535,
            integer: true
        },

        int16: {
            min: -32768,
            max: 32767,
            integer: true
        },

        uint32: {
            min: 0,
            max: 4294967295,
            integer: true
        },

        int32: {
            min: -2147483648,
            max: 2147483647,
            integer: true
        }
    };


    if (
        ranges[type]
    ) {

        const range =
            ranges[type];


        if (
            numericValue < range.min ||
            numericValue > range.max
        ) {

            node.error(
                `Validate Write: valor fuera de rango ` +
                `para ${type}: ${numericValue}`
            );

            return null;
        }


        if (
            range.integer &&
            !Number.isInteger(numericValue)
        ) {

            node.error(
                `Validate Write: ${msg.point} ` +
                `requiere un valor entero.`
            );

            return null;
        }
    }


    // ----------------------------------------------
    // Límites configurables
    // ----------------------------------------------

    if (
        msg.variable.min !== undefined
    ) {

        const min =
            Number(msg.variable.min);


        if (
            Number.isFinite(min) &&
            numericValue < min
        ) {

            node.error(
                `Validate Write: ${numericValue} menor ` +
                `al mínimo ${min} para ${msg.point}.`
            );

            return null;
        }
    }


    if (
        msg.variable.max !== undefined
    ) {

        const max =
            Number(msg.variable.max);


        if (
            Number.isFinite(max) &&
            numericValue > max
        ) {

            node.error(
                `Validate Write: ${numericValue} mayor ` +
                `al máximo ${max} para ${msg.point}.`
            );

            return null;
        }
    }
}


// ======================================================
// 12. METADATA NORMALIZADA
// ======================================================

msg.writeMeta = {

    gateway:
        requestedGatewayId,

    device:
        msg.device.id,

    variable:
        msg.point,

    type:
        type,

    fc:
        writeFc,

    address:
        address,

    quantity:
        quantity,

    unitid:
        unitid
};


// ======================================================
// OK
// ======================================================

return msg;

// ======================================================
// BUILD MODBUS WRITE
// ======================================================
//
// RESPONSABILIDAD:
//
// Convertir una solicitud YA VALIDADA en una petición
// Modbus exacta para Modbus-Flex-Write.
//
// ENTRADA:
//
// msg.writeRequest
// msg.writeMeta
// msg.variable
//
// SALIDA:
//
// msg.payload = {
//     fc,
//     address,
//     quantity,
//     unitid,
//     value
// }
//
// IMPORTANTE:
//
// - FUXA NO decide address / fc / unitid.
// - Todos esos datos vienen del driver/device.
// - Se genera un mensaje NUEVO y compacto.
// - Los valores 32-bit / float se codifican en registros.
// - multiplier se invierte al escribir.
//
// ======================================================


// ======================================================
// 1. VALIDACIONES INTERNAS
// ======================================================

if (
    !msg.writeRequest ||
    typeof msg.writeRequest !== "object"
) {

    node.error(
        "Build Modbus Write: falta msg.writeRequest"
    );

    return null;
}


if (
    !msg.writeMeta ||
    typeof msg.writeMeta !== "object"
) {

    node.error(
        "Build Modbus Write: falta msg.writeMeta"
    );

    return null;
}


if (
    !msg.variable ||
    typeof msg.variable !== "object"
) {

    node.error(
        "Build Modbus Write: falta msg.variable"
    );

    return null;
}


const meta =
    msg.writeMeta;


const variable =
    msg.variable;


const type =
    meta.type;


const fc =
    Number(meta.fc);


const address =
    Number(meta.address);


const unitid =
    Number(meta.unitid);


const requestedValue =
    msg.writeRequest.value;


// ======================================================
// 2. HELPERS
// ======================================================

function parseBool(value) {

    if (
        value === true ||
        value === 1 ||
        value === "1"
    ) {

        return true;
    }


    if (
        value === false ||
        value === 0 ||
        value === "0"
    ) {

        return false;
    }


    if (
        typeof value === "string"
    ) {

        const normalized =
            value.trim().toLowerCase();


        if (
            normalized === "true"
        ) {

            return true;
        }


        if (
            normalized === "false"
        ) {

            return false;
        }
    }


    return null;
}


// ------------------------------------------------------
// Aplicar escalado inverso.
//
// Acquisition:
//
//     engineeringValue = rawValue * multiplier
//
// Writer:
//
//     rawValue = engineeringValue / multiplier
//
// ------------------------------------------------------

function inverseMultiplier(value) {

    let result =
        Number(value);


    if (
        !Number.isFinite(result)
    ) {

        return NaN;
    }


    if (
        variable.multiplier !== undefined
    ) {

        const multiplier =
            Number(
                variable.multiplier
            );


        if (
            !Number.isFinite(multiplier) ||
            multiplier === 0
        ) {

            return NaN;
        }


        result =
            result /
            multiplier;
    }


    return result;
}


// ------------------------------------------------------
// Validar entero teniendo en cuenta pequeños errores
// de punto flotante.
//
// Ejemplo:
//
// 1.2 / 0.1
//
// puede producir:
//
// 11.999999999999998
//
// ------------------------------------------------------

function normalizeInteger(value) {

    if (
        !Number.isFinite(value)
    ) {

        return null;
    }


    const rounded =
        Math.round(value);


    if (
        Math.abs(
            value - rounded
        ) > 1e-9
    ) {

        return null;
    }


    return rounded;
}


// ======================================================
// 3. ENCODIFICACIÓN
// ======================================================

let modbusValue;
let quantity;


// ======================================================
// BOOL
// ======================================================

if (
    type === "bool"
) {

    if (
        fc !== 5
    ) {

        node.error(
            `Build Modbus Write: ${msg.point} es BOOL ` +
            `pero usa FC${fc}. Se esperaba FC5.`
        );

        return null;
    }


    const boolValue =
        parseBool(
            requestedValue
        );


    if (
        boolValue === null
    ) {

        node.error(
            `Build Modbus Write: BOOL inválido ` +
            `para ${msg.point}.`
        );

        return null;
    }


    quantity =
        1;


    modbusValue =
        boolValue;
}


// ======================================================
// UINT16
// ======================================================

else if (
    type === "uint16"
) {

    if (
        fc !== 6 &&
        fc !== 16
    ) {

        node.error(
            `Build Modbus Write: ${msg.point} es UINT16 ` +
            `pero usa FC${fc}.`
        );

        return null;
    }


    const scaled =
        inverseMultiplier(
            requestedValue
        );


    const value =
        normalizeInteger(
            scaled
        );


    if (
        value === null ||
        value < 0 ||
        value > 65535
    ) {

        node.error(
            `Build Modbus Write: UINT16 inválido ` +
            `para ${msg.point}.`
        );

        return null;
    }


    quantity =
        1;


    modbusValue =
        (
            fc === 16
        )
            ? [value]
            : value;
}


// ======================================================
// INT16
// ======================================================

else if (
    type === "int16"
) {

    if (
        fc !== 6 &&
        fc !== 16
    ) {

        node.error(
            `Build Modbus Write: ${msg.point} es INT16 ` +
            `pero usa FC${fc}.`
        );

        return null;
    }


    const scaled =
        inverseMultiplier(
            requestedValue
        );


    const value =
        normalizeInteger(
            scaled
        );


    if (
        value === null ||
        value < -32768 ||
        value > 32767
    ) {

        node.error(
            `Build Modbus Write: INT16 inválido ` +
            `para ${msg.point}.`
        );

        return null;
    }


    // ----------------------------------------------
    // Convertir número firmado a palabra Modbus
    // 0..65535 mediante complemento a dos.
    // ----------------------------------------------

    const buffer =
        Buffer.alloc(2);


    buffer.writeInt16BE(
        value,
        0
    );


    const register =
        buffer.readUInt16BE(0);


    quantity =
        1;


    modbusValue =
        (
            fc === 16
        )
            ? [register]
            : register;
}


// ======================================================
// UINT32
// ======================================================

else if (
    type === "uint32"
) {

    if (
        fc !== 16
    ) {

        node.error(
            `Build Modbus Write: ${msg.point} es UINT32 ` +
            `y requiere FC16.`
        );

        return null;
    }


    const scaled =
        inverseMultiplier(
            requestedValue
        );


    const value =
        normalizeInteger(
            scaled
        );


    if (
        value === null ||
        value < 0 ||
        value > 4294967295
    ) {

        node.error(
            `Build Modbus Write: UINT32 inválido ` +
            `para ${msg.point}.`
        );

        return null;
    }


    const buffer =
        Buffer.alloc(4);


    buffer.writeUInt32BE(
        value,
        0
    );


    const highWord =
        buffer.readUInt16BE(0);


    const lowWord =
        buffer.readUInt16BE(2);


    // ----------------------------------------------
    // IMPORTANTE:
    //
    // Respetamos exactamente la convención actual
    // de Decode Value para UINT32.
    // ----------------------------------------------

    if (
        variable.swap === true
    ) {

        modbusValue = [
            highWord,
            lowWord
        ];

    } else {

        modbusValue = [
            lowWord,
            highWord
        ];
    }


    quantity =
        2;
}


// ======================================================
// INT32
// ======================================================

else if (
    type === "int32"
) {

    if (
        fc !== 16
    ) {

        node.error(
            `Build Modbus Write: ${msg.point} es INT32 ` +
            `y requiere FC16.`
        );

        return null;
    }


    const scaled =
        inverseMultiplier(
            requestedValue
        );


    const value =
        normalizeInteger(
            scaled
        );


    if (
        value === null ||
        value < -2147483648 ||
        value > 2147483647
    ) {

        node.error(
            `Build Modbus Write: INT32 inválido ` +
            `para ${msg.point}.`
        );

        return null;
    }


    const buffer =
        Buffer.alloc(4);


    buffer.writeInt32BE(
        value,
        0
    );


    const highWord =
        buffer.readUInt16BE(0);


    const lowWord =
        buffer.readUInt16BE(2);


    // ----------------------------------------------
    // Inverso exacto del Decode Value actual.
    // ----------------------------------------------

    if (
        variable.swap === true
    ) {

        modbusValue = [
            lowWord,
            highWord
        ];

    } else {

        modbusValue = [
            highWord,
            lowWord
        ];
    }


    quantity =
        2;
}


// ======================================================
// FLOAT
// ======================================================

else if (
    type === "float"
) {

    if (
        fc !== 16
    ) {

        node.error(
            `Build Modbus Write: ${msg.point} es FLOAT ` +
            `y requiere FC16.`
        );

        return null;
    }


    const value =
        inverseMultiplier(
            requestedValue
        );


    if (
        !Number.isFinite(value)
    ) {

        node.error(
            `Build Modbus Write: FLOAT inválido ` +
            `para ${msg.point}.`
        );

        return null;
    }


    const buffer =
        Buffer.alloc(4);


    buffer.writeFloatBE(
        value,
        0
    );


    const highWord =
        buffer.readUInt16BE(0);


    const lowWord =
        buffer.readUInt16BE(2);


    // ----------------------------------------------
    // Inverso exacto del Decode Value actual.
    // ----------------------------------------------

    if (
        variable.swap === true
    ) {

        modbusValue = [
            lowWord,
            highWord
        ];

    } else {

        modbusValue = [
            highWord,
            lowWord
        ];
    }


    quantity =
        2;
}


// ======================================================
// TIPO NO SOPORTADO
// ======================================================

else {

    node.error(
        `Build Modbus Write: tipo no soportado: ${type}`
    );

    return null;
}


// ======================================================
// 4. CONSTRUIR PETICIÓN MODBUS
// ======================================================

const modbusRequest = {

    fc:
        fc,

    address:
        address,

    quantity:
        quantity,

    unitid:
        unitid,

    value:
        modbusValue
};


// ======================================================
// 5. MENSAJE COMPACTO
// ======================================================
//
// No propagamos:
//
// - device completo
// - driver completo
// - variable completa
// - estructuras de configuración
//
// Conservamos sólo metadata pequeña para poder
// auditar posteriormente el resultado.
//
// ======================================================

const outputMsg = {

    _msgid:
        msg._msgid,

    gateway: {

        id:
            meta.gateway
    },

    writeMeta: {

        gateway:
            meta.gateway,

        device:
            meta.device,

        variable:
            meta.variable,

        type:
            type,

        fc:
            fc,

        address:
            address,

        quantity:
            quantity,

        unitid:
            unitid,

        requestedValue:
            requestedValue,

        timestamp:
            Date.now()
    },

    payload:
        modbusRequest
};


if (
    typeof msg.topic === "string"
) {

    outputMsg.topic =
        msg.topic;
}


// ======================================================
// SALIDA
// ======================================================

return outputMsg;

// ======================================================
// MQTT COMMAND SAFETY GUARD
// ======================================================
//
// Protege al Modbus Writer contra comandos MQTT retained.
//
// ENTRADA:
//
//   bms/<gateway>/<device>/<variable>/write
//
// SALIDA 1:
//   Comando NUEVO autorizado para continuar al Writer.
//
// SALIDA 2:
//   Tombstone MQTT para eliminar cualquier retained
//   asociado al topic.
//
// REGLAS:
//
// 1. Un comando retained histórico NUNCA se ejecuta.
//
// 2. Todo comando nuevo se elimina inmediatamente
//    del almacenamiento retained del broker.
//
// 3. Un payload vacío corresponde al tombstone generado
//    por este mismo mecanismo y se ignora.
//
// ======================================================


// ======================================================
// 1. VALIDAR TOPIC
// ======================================================

if (
    typeof msg.topic !== "string" ||
    msg.topic.trim() === ""
) {

    node.error(
        "Command Safety Guard: msg.topic inválido."
    );

    return [
        null,
        null
    ];
}


const topic =
    msg.topic.trim();


const parts =
    topic.split("/");


if (
    parts.length !== 5 ||
    parts[0] !== "bms" ||
    parts[4] !== "write"
) {

    node.error(
        "Command Safety Guard: topic de escritura inválido: " +
        topic
    );

    return [
        null,
        null
    ];
}


// ======================================================
// 2. DETECTAR PAYLOAD VACÍO
// ======================================================
//
// Un retained se elimina publicando:
//
//     payload vacío
//     retain = true
//
// Ese mensaje también puede llegar al MQTT IN.
//
// Nunca debe convertirse nuevamente en una escritura.
// ======================================================

let emptyPayload = false;


if (
    msg.payload === null ||
    msg.payload === undefined
) {

    emptyPayload = true;

}
else if (
    Buffer.isBuffer(msg.payload)
) {

    emptyPayload =
        msg.payload.length === 0;

}
else if (
    typeof msg.payload === "string"
) {

    emptyPayload =
        msg.payload.length === 0;
}


// Tombstone recibido.
//
// No ejecutar.
// No volver a generar otro tombstone,
// evitando cualquier posibilidad de loop.
if (emptyPayload) {

    node.status({

        fill: "grey",

        shape: "ring",

        text: "TOMBSTONE"

    });


    return [
        null,
        null
    ];
}


// ======================================================
// 3. PREPARAR LIMPIEZA DEL RETAINED
// ======================================================

const clearMsg = {

    topic:
        topic,

    payload:
        "",

    qos:
        0,

    retain:
        true,

    commandCleanup:
        true,

    timestamp:
        Date.now()

};


// ======================================================
// 4. COMANDO RETAINED HISTÓRICO
// ======================================================
//
// MQTT marca msg.retain = true cuando entrega un valor
// retained existente al establecer la suscripción.
//
// Ese comando pertenece al pasado.
//
// Se elimina del broker,
// pero NUNCA continúa al Writer.
// ======================================================

if (
    msg.retain === true
) {

    node.status({

        fill: "yellow",

        shape: "ring",

        text: "RETAINED BLOCKED"

    });


    node.warn(
        "MQTT COMMAND BLOCKED - retained histórico: " +
        topic
    );


    return [

        null,

        clearMsg

    ];
}


// ======================================================
// 5. COMANDO NUEVO
// ======================================================
//
// Se permite UNA ejecución.
//
// En paralelo se envía el tombstone.
//
// Esto también cubre el caso donde el publisher
// haya usado retain=true accidentalmente:
// el comando actual se procesa una sola vez y
// el retained se elimina inmediatamente.
// ======================================================

node.status({

    fill: "green",

    shape: "dot",

    text: "COMMAND ACCEPTED"

});


return [

    msg,

    clearMsg

];

// ============================================
// ALARM FILTER
// ============================================
//
// Solo deja pasar variables configuradas
// explícitamente como alarmas en el driver.
// ============================================

if (!msg.variable) {
    return null;
}

// Esta variable no es una alarma
if (msg.variable.alarm !== true) {
    return null;
}

// Obtener valor decodificado
if (
    !msg.payload ||
    typeof msg.payload.value !== "number"
) {
    node.error(
        "Alarm Filter: valor inválido para " +
        msg.point
    );

    return null;
}

const value = msg.payload.value;

// Por ahora nuestro Alarm Engine trabaja
// exclusivamente con alarmas binarias.
if (value !== 0 && value !== 1) {

    node.error(
        "Alarm Filter: " +
        msg.point +
        " debe ser 0 o 1. Valor recibido: " +
        value
    );

    return null;
}

msg.alarmValue = value;

return msg;

// ============================================
// BINARY ALARM ENGINE
// ============================================
//
// 0 = NORMAL
// 1 = ALARMA
//
// Detecta cambios de estado y genera
// eventos para Notification Engine.
//
// Política de arranque:
//
// Primera lectura = 0
//      Guardar NORMAL.
//
// Primera lectura = 1
//      Generar ALARMA inmediatamente.
//
// ============================================


// --------------------------------------------
// Validaciones
// --------------------------------------------

if (!msg.device || !msg.device.id) {
    node.error("Alarm Engine: falta device.id");
    return null;
}

if (!msg.point) {
    node.error("Alarm Engine: falta msg.point");
    return null;
}

if (!msg.variable) {
    node.error("Alarm Engine: falta msg.variable");
    return null;
}

const value = msg.alarmValue;

if (value !== 0 && value !== 1) {
    node.error(
        "Alarm Engine: valor no binario: " +
        value
    );

    return null;
}


// --------------------------------------------
// Identificación
// --------------------------------------------

const deviceId = msg.device.id;

const deviceName =
    msg.device.name || deviceId;

const pointId = msg.point;

const pointName =
    msg.variable.name || pointId;

const alarmId =
    deviceId + "." + pointId;


// --------------------------------------------
// Metadata desde Driver
// --------------------------------------------

const severity =
    msg.variable.severity || "CRITICAL";

const alarmMessage =
    msg.variable.message || pointName;

const unit =
    msg.variable.unit || "";


// --------------------------------------------
// Runtime de alarmas
// --------------------------------------------

let states =
    flow.get("alarmStates") || {};

const previous =
    states[alarmId];

const now = Date.now();


// ============================================
// PRIMERA LECTURA
// ============================================

if (previous === undefined) {

    states[alarmId] = {
        state: value,
        since: now
    };

    flow.set(
        "alarmStates",
        states
    );


    // Primera lectura NORMAL
    //
    // Solo registramos el estado.
    // No existe evento que notificar.

    if (value === 0) {
        return null;
    }


    // ----------------------------------------
    // Primera lectura = ALARMA
    //
    // IMPORTANTE:
    // Se notifica aunque el BMS recién
    // haya arrancado.
    // ----------------------------------------

    msg.alarm = {

        id: alarmId,

        timestamp: now,

        device: {
            id: deviceId,
            name: deviceName
        },

        point: {
            id: pointId,
            name: pointName
        },

        value: 1,

        unit: unit,

        severity: severity,

        state: "ACTIVE",

        message: alarmMessage
    };

    return msg;
}


// ============================================
// MISMO ESTADO
// ============================================

if (previous.state === value) {

    // 0 → 0
    // o
    // 1 → 1

    // No generar otra notificación.

    return null;
}


// ============================================
// 0 → 1
// NUEVA ALARMA
// ============================================

if (
    previous.state === 0 &&
    value === 1
) {

    states[alarmId] = {
        state: 1,
        since: now
    };

    flow.set(
        "alarmStates",
        states
    );


    msg.alarm = {

        id: alarmId,

        timestamp: now,

        device: {
            id: deviceId,
            name: deviceName
        },

        point: {
            id: pointId,
            name: pointName
        },

        value: 1,

        unit: unit,

        severity: severity,

        state: "ACTIVE",

        message: alarmMessage
    };

    return msg;
}


// ============================================
// 1 → 0
// RESTABLECIMIENTO
// ============================================

if (
    previous.state === 1 &&
    value === 0
) {

    const activeSince =
        previous.since;

    const duration =
        now - activeSince;


    states[alarmId] = {
        state: 0,
        since: now
    };

    flow.set(
        "alarmStates",
        states
    );


    msg.alarm = {

        id: alarmId,

        timestamp: now,

        device: {
            id: deviceId,
            name: deviceName
        },

        point: {
            id: pointId,
            name: pointName
        },

        value: 0,

        unit: unit,

        // Mantenemos la severidad original
        // para que Notification Engine pueda
        // seguir enviando el restablecimiento.
        severity: severity,

        state: "CLEARED",

        message: alarmMessage,

        durationMs: duration
    };

    return msg;
}


return null;

// ============================================
// BUILD TEST ALARM
// ============================================
//
// Simula exactamente la información necesaria
// para que Alarm Filter y Binary Alarm Engine
// procesen una alarma.
//
// msg.payload llega desde los Inject:
//
// 0 = NORMAL
// 1 = ALARMA
//
// Usamos un device ID de simulación para NO
// interferir con el estado de la alarma real.
// ============================================


// --------------------------------------------
// OBTENER VALOR DEL INJECT
// --------------------------------------------

const value = Number(msg.payload);


// --------------------------------------------
// VALIDAR
// --------------------------------------------

if (value !== 0 && value !== 1) {

    node.error(
        "Build Test Alarm: el valor debe ser 0 o 1"
    );

    return null;
}


// --------------------------------------------
// SIMULAR DISPOSITIVO
// --------------------------------------------

msg.device = {

    id: "SIM_COMPRESSORS",

    name: "Sala de Compresores"
};


// --------------------------------------------
// SIMULAR PUNTO
// --------------------------------------------

msg.point = "AlarmCompressors";


// --------------------------------------------
// SIMULAR DEFINICIÓN DEL DRIVER
// --------------------------------------------

msg.variable = {

    name: "Alarma Compresores",

    address: 3472,

    quantity: 1,

    type: "uint16",

    multiplier: 1,

    unit: "",

    decimals: 0,

    alarm: true,

    severity: "CRITICAL",

    message:
        "Se detectó una alarma en la sala de compresores"
};


// --------------------------------------------
// SIMULAR SALIDA DE DECODE VALUE
// --------------------------------------------

msg.payload = {

    point: msg.point,

    value: value
};


// --------------------------------------------
// SALIDA
// --------------------------------------------

return msg;

// ============================================
// ALARM FORMATTER
// ============================================
//
// RESPONSABILIDAD:
//
// Convertir msg.alarm en un mensaje breve,
// claro y orientado a personas.
//
// Genera:
//
//     msg.whatsappMessage
//
// El contenido técnico permanece en msg.alarm,
// pero no se muestra al usuario.
//
// ============================================


const alarm =
    msg.alarm;


// ============================================
// VALIDACIÓN
// ============================================

if (
    !alarm ||
    typeof alarm !== "object"
) {

    node.error(
        "Alarm Formatter: no existe msg.alarm"
    );

    return null;
}


if (
    !alarm.device
) {

    node.error(
        "Alarm Formatter: falta alarm.device"
    );

    return null;
}


if (
    !alarm.point
) {

    node.error(
        "Alarm Formatter: falta alarm.point"
    );

    return null;
}


if (
    !alarm.state
) {

    node.error(
        "Alarm Formatter: falta alarm.state"
    );

    return null;
}


// ============================================
// FECHA
// ============================================

const date =
    new Date(
        alarm.timestamp
    );


const dateString =
    date.toLocaleString(
        "es-UY",
        {
            timeZone:
                "America/Montevideo"
        }
    );


// ============================================
// SEVERIDAD
// ============================================

let severityText =
    alarm.severity ||
    "DESCONOCIDA";


switch (
    alarm.severity
) {

    case "CRITICAL":

        severityText =
            "CRÍTICA";

        break;


    case "WARNING":

        severityText =
            "ADVERTENCIA";

        break;


    case "INFO":

        severityText =
            "INFORMACIÓN";

        break;
}


// ============================================
// DURACIÓN
// ============================================

let durationText =
    "";


if (
    alarm.state === "CLEARED" &&
    typeof alarm.durationMs === "number"
) {

    const totalSeconds =
        Math.floor(
            alarm.durationMs / 1000
        );


    const hours =
        Math.floor(
            totalSeconds / 3600
        );


    const minutes =
        Math.floor(
            (totalSeconds % 3600) / 60
        );


    const seconds =
        totalSeconds % 60;


    if (
        hours > 0
    ) {

        durationText =
            `${hours} h ${minutes} min ${seconds} s`;

    }
    else if (
        minutes > 0
    ) {

        durationText =
            `${minutes} min ${seconds} s`;

    }
    else {

        durationText =
            `${seconds} s`;
    }
}


// ============================================
// ALARMA ACTIVA
// ============================================

if (
    alarm.state === "ACTIVE"
) {

    let icon =
        "⚠️";


    switch (
        alarm.severity
    ) {

        case "CRITICAL":

            icon =
                "🚨";

            break;


        case "WARNING":

            icon =
                "⚠️";

            break;


        case "INFO":

            icon =
                "ℹ️";

            break;
    }


    msg.whatsappMessage =

`${icon} *ALARMA BMS*

*Equipo:* ${alarm.device.name}
*Alarma:* ${alarm.point.name}
*Estado:* ACTIVA
*Severidad:* ${severityText}

${alarm.message}

*Fecha:* ${dateString}`;


    return msg;
}


// ============================================
// ALARMA RESTABLECIDA
// ============================================

if (
    alarm.state === "CLEARED"
) {

    let message =

`✅ *ALARMA RESTABLECIDA*

*Equipo:* ${alarm.device.name}
*Alarma:* ${alarm.point.name}
*Estado:* NORMAL

${alarm.message}

*Fecha:* ${dateString}`;


    if (
        durationText
    ) {

        message +=
            `\n*Duración:* ${durationText}`;
    }


    msg.whatsappMessage =
        message;


    return msg;
}


// ============================================
// ESTADO DESCONOCIDO
// ============================================

node.error(
    "Alarm Formatter: estado desconocido: " +
    alarm.state
);

return null;

// ======================================================
// SEVERITY / ROUTING
// ======================================================
//
// RESPONSABILIDAD:
//
// 1. Determinar qué canales CORRESPONDEN según severidad.
// 2. Consultar qué canales están HABILITADOS en system.json.
// 3. Generar el routing efectivo.
//
// POLÍTICA:
//
// CRITICAL
//   WhatsApp : sí
//   Email    : sí
//   Telegram : sí
//
// WARNING
//   WhatsApp : sí
//   Email    : sí
//   Telegram : no
//
// INFO
//   No genera notificación externa.
//
// IMPORTANTE:
//
// Un canal sólo se utiliza cuando:
//
//   política === true
//          Y
//   enabled === true
//
// ======================================================


// ======================================================
// 1. VALIDAR ALARMA
// ======================================================

const alarm =
    msg.alarm;


if (
    !alarm ||
    typeof alarm !== "object"
) {

    node.error(
        "Severity / Routing: no existe msg.alarm"
    );

    return null;
}


if (
    typeof alarm.severity !== "string"
) {

    node.error(
        "Severity / Routing: falta severity"
    );

    return null;
}


if (
    alarm.state !== "ACTIVE" &&
    alarm.state !== "CLEARED"
) {

    node.error(
        "Severity / Routing: estado inválido: " +
        alarm.state
    );

    return null;
}


// ======================================================
// 2. SYSTEM CONFIG
// ======================================================

const systemConfig =
    global.get("systemConfig");


if (
    !systemConfig ||
    typeof systemConfig !== "object"
) {

    node.error(
        "Severity / Routing: systemConfig no está cargado."
    );

    return null;
}


const notifications =
    systemConfig.notifications;


if (
    !notifications ||
    typeof notifications !== "object"
) {

    node.error(
        "Severity / Routing: falta configuración notifications."
    );

    return null;
}


// ======================================================
// 3. DISPONIBILIDAD DE CANALES
// ======================================================

const enabled = {

    whatsapp:
        notifications.whatsapp?.enabled === true,

    email:
        notifications.email?.enabled === true,

    telegram:
        notifications.telegram?.enabled === true
};


// ======================================================
// 4. POLÍTICA SEGÚN SEVERIDAD
// ======================================================

const policy = {

    whatsapp:
        false,

    email:
        false,

    telegram:
        false
};


switch (
    alarm.severity
) {

    // ==================================================
    // CRITICAL
    // ==================================================

    case "CRITICAL":

        policy.whatsapp =
            true;

        policy.email =
            true;

        policy.telegram =
            true;

        break;


    // ==================================================
    // WARNING
    // ==================================================

    case "WARNING":

        policy.whatsapp =
            true;

        policy.email =
            true;

        policy.telegram =
            false;

        break;


    // ==================================================
    // INFO
    // ==================================================

    case "INFO":

        // Sólo registro interno.

        policy.whatsapp =
            false;

        policy.email =
            false;

        policy.telegram =
            false;

        break;


    // ==================================================
    // SEVERIDAD DESCONOCIDA
    // ==================================================

    default:

        node.error(
            "Severity / Routing: severidad desconocida: " +
            alarm.severity
        );

        return null;
}


// ======================================================
// 5. ROUTING EFECTIVO
// ======================================================
//
// Canal efectivo =
//
//     policy && enabled
//
// ======================================================

msg.routing = {

    whatsapp:
        policy.whatsapp &&
        enabled.whatsapp,

    email:
        policy.email &&
        enabled.email,

    telegram:
        policy.telegram &&
        enabled.telegram
};


// ======================================================
// 6. METADATA DE DIAGNÓSTICO
// ======================================================
//
// Útil para Debug y para el futuro manual.
//
// routingPolicy:
//
//   qué debería enviarse por severidad
//
// notificationChannels:
//
//   qué está actualmente habilitado
//
// routing:
//
//   qué realmente se enviará
//
// ======================================================

msg.routingPolicy = {

    whatsapp:
        policy.whatsapp,

    email:
        policy.email,

    telegram:
        policy.telegram
};


msg.notificationChannels = {

    whatsapp:
        enabled.whatsapp,

    email:
        enabled.email,

    telegram:
        enabled.telegram
};


// ======================================================
// 7. STATUS
// ======================================================

const activeChannels =
    Object.entries(msg.routing)
        .filter(
            ([, value]) =>
                value === true
        )
        .map(
            ([key]) =>
                key
        );


if (
    activeChannels.length === 0
) {

    node.status({

        fill:
            "grey",

        shape:
            "ring",

        text:
            "SIN CANALES EXTERNOS"

    });

}
else {

    node.status({

        fill:
            "green",

        shape:
            "dot",

        text:
            activeChannels.join(", ")

    });
}


// ======================================================
// SALIDA
// ======================================================

return msg;

// ============================================
// PREPARE WHATSAPP
// ============================================

if (!msg.whatsappMessage) {
    node.error("No existe msg.whatsappMessage");
    return null;
}

msg.payload = msg.whatsappMessage;

return msg;

// ============================================
// ALARM LOG
// ============================================
//
// Registro temporal de eventos de alarma.
//
// Más adelante esta salida irá a la
// base de datos histórica.
// ============================================


const alarm = msg.alarm;


// --------------------------------------------
// VALIDACIÓN
// --------------------------------------------

if (!alarm) {
    node.error("Alarm Log: no existe msg.alarm");
    return null;
}


// --------------------------------------------
// CREAR REGISTRO
// --------------------------------------------

const logEntry = {

    timestamp: alarm.timestamp,

    id: alarm.id,

    device: alarm.device,

    point: alarm.point,

    value: alarm.value,

    unit: alarm.unit,

    severity: alarm.severity,

    state: alarm.state,

    message: alarm.message,

    durationMs:
        alarm.durationMs !== undefined
            ? alarm.durationMs
            : null
};


// --------------------------------------------
// OBTENER LOG ACTUAL
// --------------------------------------------

let alarmLog =
    flow.get("alarmLog") || [];


// --------------------------------------------
// AGREGAR EVENTO
// --------------------------------------------

alarmLog.push(logEntry);


// --------------------------------------------
// LIMITAR MEMORIA
// --------------------------------------------
//
// Por ahora mantenemos los últimos
// 1000 eventos.
//
// Cuando usemos InfluxDB esto dejará de ser
// nuestro almacenamiento definitivo.
// --------------------------------------------

if (alarmLog.length > 1000) {

    alarmLog.shift();
}


// --------------------------------------------
// GUARDAR
// --------------------------------------------

flow.set(
    "alarmLog",
    alarmLog
);


// --------------------------------------------
// SALIDA
// --------------------------------------------

msg.payload = logEntry;

return msg;

// ============================================
// PREPARE EMAIL
// ============================================
//
// RESPONSABILIDAD:
//
// Recibir un evento normalizado:
//
//     msg.alarm
//
// y generar un mensaje NUEVO y mínimo
// destinado exclusivamente al nodo de Email.
//
// SALIDA:
//
//     msg._msgid
//     msg.to
//     msg.topic
//     msg.payload
//
// NO propagamos:
//
// - whatsappMessage
// - routing
// - alarm
// - alarmValue
// - healthAlarm
// - device
// - variable
// - point
// - _event
// - metadata de otros canales
//
// ============================================


// ============================================
// 1. ALARMA
// ============================================

const alarm =
    msg.alarm;


// ============================================
// 2. VALIDACIÓN
// ============================================

if (
    !alarm ||
    typeof alarm !== "object"
) {

    node.error(
        "Prepare Email: no existe msg.alarm"
    );

    return null;
}


if (
    !alarm.device ||
    typeof alarm.device !== "object"
) {

    node.error(
        "Prepare Email: falta alarm.device"
    );

    return null;
}


if (
    !alarm.point ||
    typeof alarm.point !== "object"
) {

    node.error(
        "Prepare Email: falta alarm.point"
    );

    return null;
}


if (
    typeof alarm.timestamp !== "number"
) {

    node.error(
        "Prepare Email: timestamp inválido"
    );

    return null;
}


// ============================================
// 3. FECHA
// ============================================

const date =
    new Date(
        alarm.timestamp
    );


const dateString =
    date.toLocaleString(
        "es-UY",
        {
            timeZone:
                "America/Montevideo"
        }
    );


// ============================================
// 4. SEVERIDAD
// ============================================

let severityText =
    alarm.severity || "UNKNOWN";


switch (
    alarm.severity
) {

    case "CRITICAL":

        severityText =
            "CRÍTICA";

        break;


    case "WARNING":

        severityText =
            "ADVERTENCIA";

        break;


    case "INFO":

        severityText =
            "INFORMACIÓN";

        break;
}


// ============================================
// 5. ESTADO
// ============================================

let stateText;
let subjectPrefix;


if (
    alarm.state === "ACTIVE"
) {

    stateText =
        "ACTIVA";

    subjectPrefix =
        "ALARMA BMS";

}
else if (
    alarm.state === "CLEARED"
) {

    stateText =
        "RESTABLECIDA";

    subjectPrefix =
        "ALARMA RESTABLECIDA";

}
else {

    node.error(
        "Prepare Email: estado desconocido: " +
        alarm.state
    );

    return null;
}


// ============================================
// 6. DURACIÓN
// ============================================

let durationText =
    "";


if (
    alarm.state === "CLEARED" &&
    typeof alarm.durationMs === "number"
) {

    const totalSeconds =
        Math.floor(
            alarm.durationMs / 1000
        );


    const hours =
        Math.floor(
            totalSeconds / 3600
        );


    const minutes =
        Math.floor(
            (totalSeconds % 3600) / 60
        );


    const seconds =
        totalSeconds % 60;


    if (
        hours > 0
    ) {

        durationText =
            `${hours} h ${minutes} min ${seconds} s`;

    }
    else if (
        minutes > 0
    ) {

        durationText =
            `${minutes} min ${seconds} s`;

    }
    else {

        durationText =
            `${seconds} s`;
    }
}


// ============================================
// 7. DESTINATARIO
// ============================================
//
// TEMPORAL:
//
// Más adelante este dato debe salir de nuestro
// archivo/configuración general del BMS.
//
// ============================================

const recipient =
    "Mercolux@semm-mautone.com.uy";


// ============================================
// 8. ASUNTO
// ============================================

const subject =
    `[${subjectPrefix}] ` +
    `${alarm.device.name} - ` +
    `${alarm.point.name}`;


// ============================================
// 9. CUERPO
// ============================================

let body =

`SISTEMA BMS - SANATORIO

${subjectPrefix}

Equipo: ${alarm.device.name}
Alarma: ${alarm.point.name}
Estado: ${stateText}
Severidad: ${severityText}

Descripción:
${alarm.message}

Fecha: ${dateString}`;


// ============================================
// 10. DURACIÓN
// ============================================

if (
    durationText
) {

    body +=
        `\nDuración de la alarma: ${durationText}`;
}


// ============================================
// 11. INFORMACIÓN TÉCNICA
// ============================================

body +=

`

----------------------------------------
Información técnica

Device ID: ${alarm.device.id}
Point ID: ${alarm.point.id}
Alarm ID: ${alarm.id}
Valor: ${alarm.value}
----------------------------------------

Mensaje generado automáticamente por el sistema BMS.
`;


// ============================================
// 12. MENSAJE EMAIL LIMPIO
// ============================================
//
// IMPORTANTE:
//
// Creamos un objeto NUEVO.
//
// No hacemos:
//
//     msg.payload = body;
//     return msg;
//
// porque eso arrastraría todas las propiedades
// utilizadas anteriormente por:
//
// - Alarm Engine
// - Alarm Formatter
// - Routing
// - WhatsApp
//
// ============================================

const emailMsg = {

    _msgid:
        msg._msgid,

    to:
        recipient,

    topic:
        subject,

    payload:
        body
};


// ============================================
// 13. SALIDA
// ============================================

return emailMsg;

// ======================================================
// READ ALARM LOG
// ======================================================

const alarmLog =
    flow.get("alarmLog") || [];


msg.payload = {

    count:
        alarmLog.length,

    alarms:
        alarmLog

};


return msg;

// ======================================================
// CLEAR ALARM LOG
// ======================================================

flow.set(
    "alarmLog",
    []
);


msg.payload = {

    status:
        "OK",

    message:
        "Alarm Log limpiado",

    timestamp:
        new Date().toISOString()

};


return msg;

msg.payload = {
    gateways: global.get("gateways"),
    devices: global.get("devices"),
    drivers: global.get("drivers")
};

return msg;

const data = msg.payload;

const gateway = data.gateway;
const device = data.deviceId;

const messages = [];

for (const pointName in data.measurements) {

    const measurement = data.measurements[pointName];

    messages.push({

        topic: `bms/${gateway}/${device}/${pointName}`,

        payload: {

            value: measurement.value,

            unit: measurement.unit,

            quality: "GOOD",

            timestamp: measurement.timestamp

        }

    });

}

msg.payload = messages;

return msg;

const data = msg.payload;

const gateway = data.gateway;
const device = data.deviceId;

const messages = [];

for (const pointName in data.measurements) {
    const measurement = data.measurements[pointName];

    // Creamos un objeto de mensaje totalmente limpio desde cero
    messages.push({
        _msgid: msg._msgid, // Mantenemos el ID original de Node-RED por buenas prácticas
        topic: `bms/${gateway}/${device}/${pointName}`,
        // Enviamos SOLO el valor numérico crudo para que FUXA lo lea de forma nativa
        payload: measurement.value 
    });
}

// Reemplazamos el payload original por nuestro array de mensajes limpios
msg.payload = messages;

// Eliminamos de la raíz del mensaje toda la configuración pesada de Modbus
// para que el nodo split no la herede ni la duplique.
delete msg.device;
delete msg.driver;
delete msg.variables;
delete msg.variable;
delete msg.gateway;
delete msg.modbusRequest;
delete msg.responseBuffer;

return msg;

const regs = msg.payload;

if (!Array.isArray(regs)) {
    return null;
}

const variable = msg.variable;

let value = null;

//==================================================
// UINT16
//==================================================
if (variable.type === "uint16") {

    value = regs[0];

}

//==================================================
// INT16
//==================================================
else if (variable.type === "int16") {

    const buffer = Buffer.alloc(2);
    buffer.writeUInt16BE(regs[0],0);
    value = buffer.readInt16BE(0);

}

//==================================================
// UINT32
//==================================================
else if (variable.type === "uint32") {

    // Si llegaron 4 registros, usamos solamente los dos primeros.
    // Esto ocurre en algunos equipos (como el SCU200) que reservan
    // espacio para una futura expansión a 64 bits.

    const r0 = regs[0];
    const r1 = regs[1];

    if (variable.swap === true) {

        value = ((r0 << 16) >>> 0) + r1;

    } else {

        value = ((r1 << 16) >>> 0) + r0;

    }

}

//==================================================
// INT32
//==================================================
else if (variable.type === "int32") {

    const buffer = Buffer.alloc(4);

    if (variable.swap === true) {

        buffer.writeUInt16BE(regs[1],0);
        buffer.writeUInt16BE(regs[0],2);

    } else {

        buffer.writeUInt16BE(regs[0],0);
        buffer.writeUInt16BE(regs[1],2);

    }

    value = buffer.readInt32BE(0);

}

//==================================================
// FLOAT
//==================================================
else if (variable.type === "float") {

    const buffer = Buffer.alloc(4);

    if (variable.swap === true) {

        buffer.writeUInt16BE(regs[1],0);
        buffer.writeUInt16BE(regs[0],2);

    } else {

        buffer.writeUInt16BE(regs[0],0);
        buffer.writeUInt16BE(regs[1],2);

    }

    value = buffer.readFloatBE(0);

}

//==================================================

else {

    node.error("Tipo desconocido: " + variable.type);
    return null;

}

// Aplicar multiplicador (viejo)

if (variable.multiplier !== undefined) {

    value *= variable.multiplier;

}

// Redondeo

if (variable.decimals !== undefined) {

    value = Number(value.toFixed(variable.decimals));

}

msg.payload = {
    value: value
};

return msg;

const device = msg.device;

if (!device) {
    node.error("No llegó ningún dispositivo.");
    return null;
}

if (!device.driver) {
    node.error("El dispositivo no tiene driver.");
    return null;
}

//if (!Array.isArray(device.points)) {
//    node.error("El dispositivo no tiene lista de puntos.");
//    return null;
//}

const jobs = [];

for (const pointName of Object.keys(device.driver.variables)) {// con objects keys, dejamos de depender del puntero en devices.json

    const variable = device.driver.variables[pointName];

    if (!variable) {

        node.warn(`La variable ${pointName} no existe en el driver ${device.driver.id}`);

        continue;
    }

    jobs.push({

        device: device,

        point: pointName,

        variable: variable,

        request: {

            unitid: device.slave,

            fc: variable.fc,

            address: variable.address,

            quantity: variable.quantity

        }

    });

}

msg.payload = jobs;

return msg;

const deviceId = msg.device.id;

if (!deviceId) {
    node.error("No existe device.id");
    return null;
}

let cache = flow.get("measurements") || {};

// Crear almacenamiento del dispositivo
if (!cache[deviceId]) {
    cache[deviceId] = {};
}

// Guardar la variable recibida
cache[deviceId][msg.point] = {

    name: msg.variable.name,

    value: msg.payload.value,

    unit: msg.variable.unit,

    timestamp: new Date().toISOString()

};

// Guardar nuevamente el cache
flow.set("measurements", cache);

// ¿Cuántos puntos esperamos para este dispositivo? va a contar automaticamente segun las variables que tenga el driver
const expectedPoints = Object.keys(msg.device.driver.variables).length;

// Si todavía faltan variables, esperamos
if (Object.keys(cache[deviceId]).length < expectedPoints) {
    return null;
}

//======================================================
// Todas las variables fueron adquiridas
//======================================================

msg.payload = {

    deviceId: deviceId,

    deviceName: msg.device.name,

    gateway: msg.device.gateway.id,

    driver: msg.device.driver.id,

    timestamp: new Date().toISOString(),

    measurements: cache[deviceId]

};

// Limpiar memoria para el próximo ciclo
delete cache[deviceId];

flow.set("measurements", cache);

return msg;

// ======================================================
// HEARTBEAT OBSERVER
// ======================================================
//
// RESPONSABILIDAD:
//
// Observar ÚNICAMENTE los devices que tienen un
// heartbeat configurado.
//
// Para esos devices:
//
// - detecta el valor actual
// - recuerda el valor anterior
// - registra cuándo cambió por última vez
//
// NO determina OFFLINE.
// Eso pertenece a Communication / Watchdog.
// ======================================================


// ------------------------------------------------------
// VALIDAR DEVICE
// ------------------------------------------------------

if (
    !msg.device ||
    !msg.device.id
) {

    return null;
}


const deviceId =
    msg.device.id;


// ======================================================
// ¿EL DEVICE TIENE HEARTBEAT?
// ======================================================

const heartbeatPoint =
    msg.device.health?.heartbeatPoint;


if (
    typeof heartbeatPoint !== "string" ||
    heartbeatPoint.trim() === ""
) {

    // Device sin heartbeat.
    //
    // Esto NO es un error.
    //
    // SCU200, ABB y futuros equipos pueden entrar
    // perfectamente por este camino.

    return null;
}


// ======================================================
// ¿ESTE MENSAJE ES EL HEARTBEAT?
// ======================================================

if (
    msg.point !== heartbeatPoint
) {

    return null;
}


// ======================================================
// VALOR DECODIFICADO
// ======================================================

const value =
    msg.payload?.value;


if (
    value === undefined ||
    value === null
) {

    node.warn(
        `Heartbeat ${deviceId}: valor inválido`
    );

    return null;
}


const now =
    Date.now();

const nowIso =
    new Date(now).toISOString();


// ======================================================
// HEALTH
// ======================================================

let health =
    global.get("health") || {};


health.devices =
    health.devices || {};


let deviceHealth =
    health.devices[deviceId];


if (!deviceHealth) {

    node.warn(
        `Heartbeat ${deviceId}: ` +
        `device todavía no existe en global.health`
    );

    return null;
}


let application =
    deviceHealth.application || {};


application.enabled =
    true;

application.heartbeatPoint =
    heartbeatPoint;


// ------------------------------------------------------
// REGISTRAMOS QUE PUDIMOS LEER EL HEARTBEAT
// ------------------------------------------------------

application.lastSeen =
    now;

application.lastSeenIso =
    nowIso;


// ======================================================
// PRIMERA LECTURA
// ======================================================

if (
    application.lastValue === undefined
) {

    application.lastValue =
        value;

    application.lastChange =
        now;

    application.lastChangeIso =
        nowIso;

    application.status =
        "GOOD";


    deviceHealth.application =
        application;


    if (
        deviceHealth.communication?.status === "GOOD"
    ) {

        deviceHealth.status =
            "GOOD";
    }


    health.devices[deviceId] =
        deviceHealth;


    health.updatedAt =
        nowIso;


    global.set(
        "health",
        health
    );


    node.status({

        fill: "green",

        shape: "dot",

        text:
            `${deviceId}: HB ${value}`
    });


    return null;
}


// ======================================================
// COMPARAR CON EL VALOR ANTERIOR
// ======================================================

if (
    value !== application.lastValue
) {

    // --------------------------------------------------
    // CAMBIÓ
    // --------------------------------------------------

    application.lastValue =
        value;

    application.lastChange =
        now;

    application.lastChangeIso =
        nowIso;

    application.status =
        "GOOD";


    if (
        deviceHealth.communication?.status === "GOOD"
    ) {

        deviceHealth.status =
            "GOOD";
    }
}


// ======================================================
// SI NO CAMBIÓ
// ======================================================
//
// NO declaramos BAD aquí.
//
// Simplemente NO actualizamos lastChange.
//
// El Watchdog medirá:
// now - lastChange
//
// y decidirá cuándo realmente está congelado.
// ======================================================


// ======================================================
// GUARDAR
// ======================================================

deviceHealth.application =
    application;


health.devices[deviceId] =
    deviceHealth;


health.updatedAt =
    nowIso;


global.set(
    "health",
    health
);


// ======================================================
// STATUS
// ======================================================

node.status({

    fill: "green",

    shape: "dot",

    text:
        `${deviceId}: HB ${value}`
});


return null;

// ======================================================
// HEALTH ALARM ADAPTER
// ======================================================
//
// Convierte estados del Health Engine al formato binario
// que ya entiende nuestro Alarm Engine.
//
// Genera:
//
// 1. Alarma de pérdida de comunicación
// 2. Alarma de aplicación / heartbeat detenido
//
// NO administra transiciones.
//
// ACTIVE / CLEARED / duración / duplicados siguen siendo
// responsabilidad del Binary Alarm Engine existente.
// ======================================================


const health =
    global.get("health") || {};


const configuredDevices =
    global.get("devices") || {};


// ======================================================
// HELPER
// ======================================================

function sendAlarmInput({

    deviceId,

    deviceName,

    gatewayId,

    pointId,

    pointName,

    value,

    severity,

    message

}) {

    node.send({

        healthAlarm:
            true,

        device: {

            id:
                deviceId,

            name:
                deviceName,

            gateway:
                gatewayId
        },

        point:
            pointId,

        variable: {

            name:
                pointName,

            type:
                "bool",

            unit:
                "",

            alarm:
                true,

            severity:
                severity,

            message:
                message
        },

        payload: {

            value:
                value
        }

    });
}


// ======================================================
// DEVICES
// ======================================================

for (
    const [deviceId, deviceHealth]
    of Object.entries(
        health.devices || {}
    )
) {

    const deviceConfig =
        configuredDevices[deviceId] || {};


    const deviceName =
        deviceConfig.name ||
        deviceHealth.name ||
        deviceId;


    const gatewayId =
        deviceConfig.gateway ||
        deviceHealth.gateway ||
        null;


    // ==================================================
    // 1. ALARMA DE COMUNICACIÓN
    // ==================================================

    const communicationStatus =
        deviceHealth.communication?.status ||
        "UNKNOWN";


    // Severidad configurable opcionalmente.
    //
    // Si no existe configuración:
    // WARNING.

    const communicationSeverity =
        deviceConfig.health
            ?.communicationAlarmSeverity ||
        "WARNING";


    // --------------------------------------------------
    // GOOD
    // --------------------------------------------------

    if (
        communicationStatus === "GOOD"
    ) {

        sendAlarmInput({

            deviceId:
                deviceId,

            deviceName:
                deviceName,

            gatewayId:
                gatewayId,

            pointId:
                "BMS_Communication",

            pointName:
                "Comunicación BMS",

            value:
                0,

            severity:
                communicationSeverity,

            message:
                "Supervisión de comunicación Modbus del equipo."
        });
    }


    // --------------------------------------------------
    // OFFLINE
    // --------------------------------------------------

    else if (
        communicationStatus === "OFFLINE"
    ) {

        sendAlarmInput({

            deviceId:
                deviceId,

            deviceName:
                deviceName,

            gatewayId:
                gatewayId,

            pointId:
                "BMS_Communication",

            pointName:
                "Comunicación BMS",

            value:
                1,

            severity:
                communicationSeverity,

            message:
                "Supervisión de comunicación Modbus del equipo."
        });
    }


    // --------------------------------------------------
    // UNKNOWN / STALE
    // --------------------------------------------------
    //
    // No enviamos mensaje.
    //
    // STALE degrada Quality pero todavía no activa
    // notificaciones.
    //
    // UNKNOWN no representa ni alarma ni recuperación.
    // --------------------------------------------------


    // ==================================================
    // 2. ALARMA DE APLICACIÓN / HEARTBEAT
    // ==================================================

    const application =
        deviceHealth.application || {};


    if (
        application.enabled !== true
    ) {

        continue;
    }


    const applicationStatus =
        application.status ||
        "UNKNOWN";


    const applicationSeverity =
        deviceConfig.health
            ?.applicationAlarmSeverity ||
        "CRITICAL";


    // --------------------------------------------------
    // GOOD
    // --------------------------------------------------

    if (
        applicationStatus === "GOOD"
    ) {

        sendAlarmInput({

            deviceId:
                deviceId,

            deviceName:
                deviceName,

            gatewayId:
                gatewayId,

            pointId:
                "BMS_ApplicationHeartbeat",

            pointName:
                "Heartbeat de aplicación",

            value:
                0,

            severity:
                applicationSeverity,

            message:
                "Supervisión de ejecución del programa mediante heartbeat."
        });
    }


    // --------------------------------------------------
    // BAD
    // --------------------------------------------------

    else if (
        applicationStatus === "BAD"
    ) {

        sendAlarmInput({

            deviceId:
                deviceId,

            deviceName:
                deviceName,

            gatewayId:
                gatewayId,

            pointId:
                "BMS_ApplicationHeartbeat",

            pointName:
                "Heartbeat de aplicación",

            value:
                1,

            severity:
                applicationSeverity,

            message:
                "Supervisión de ejecución del programa mediante heartbeat."
        });
    }


    // --------------------------------------------------
    // UNKNOWN
    // --------------------------------------------------
    //
    // NO mandamos 0.
    //
    // UNKNOWN significa "no puedo determinarlo".
    // No significa "restablecido".
    // --------------------------------------------------
}


// ======================================================
// STATUS
// ======================================================

node.status({

    fill:
        "green",

    shape:
        "dot",

    text:
        "HEALTH → ALARMS"
});


return null;

// ======================================================
// HEALTH ALARM ADAPTER
// ======================================================
//
// RESPONSABILIDAD:
//
// Convertir estados del Health Engine al formato binario
// utilizado por el Alarm Engine.
//
// SEÑALES GENERADAS:
//
// BMS_Communication
//
//     GOOD    -> 0
//     OFFLINE -> 1
//
// BMS_ApplicationHeartbeat
//
//     GOOD -> 0
//     BAD  -> 1
//
// FUNCIONAMIENTO:
//
// CHANGE-ONLY.
//
// Sólo enviamos un mensaje cuando cambia el valor
// binario respecto del último valor enviado.
//
// IMPORTANTE:
//
// Esta implementación está deliberadamente simplificada.
//
// NO utiliza:
//
// - context.get()
// - context.set()
// - Set()
// - limpieza dinámica de keys
// - node.status() en cada tick
//
// El pequeño estado interno se guarda en:
//
//     global.healthAlarmAdapterState
//
// ======================================================


// ======================================================
// 1. OBTENER DATOS
// ======================================================

const health =
    global.get("health") || {};

const configuredDevices =
    global.get("devices") || {};


// ======================================================
// 2. OBTENER CACHE DE ESTADOS
// ======================================================
//
// Ejemplo:
//
// {
//     "AIRMED.BMS_Communication": 0,
//     "AIRMED.BMS_ApplicationHeartbeat": 0,
//     "TANKS.BMS_Communication": 1
// }
//
// Es un objeto muy pequeño.
//
// Aproximadamente:
//
//     1 estado por device
//     +
//     1 estado extra si tiene heartbeat
//
// ======================================================

let lastStates =
    global.get("healthAlarmAdapterState");


if (
    !lastStates ||
    typeof lastStates !== "object" ||
    Array.isArray(lastStates)
) {

    lastStates = {};
}


// ======================================================
// 3. CONTROL DEL CICLO
// ======================================================

let cacheChanged =
    false;

let emittedCount =
    0;


// ======================================================
// 4. RECORRER DEVICES
// ======================================================

for (
    const [deviceId, deviceHealth]
    of Object.entries(
        health.devices || {}
    )
) {

    const deviceConfig =
        configuredDevices[deviceId] || {};


    // ==================================================
    // METADATA
    // ==================================================

    const deviceName =
        deviceConfig.name ||
        deviceHealth.name ||
        deviceId;


    let gatewayId =
        null;


    if (
        typeof deviceConfig.gateway === "string"
    ) {

        gatewayId =
            deviceConfig.gateway;

    } else if (
        deviceConfig.gateway &&
        typeof deviceConfig.gateway === "object"
    ) {

        gatewayId =
            deviceConfig.gateway.id || null;

    } else {

        gatewayId =
            deviceHealth.gateway || null;
    }


    // ==================================================
    // 5. COMUNICACIÓN
    // ==================================================

    const communicationStatus =
        deviceHealth.communication?.status ||
        "UNKNOWN";


    let communicationValue =
        null;


    if (
        communicationStatus === "GOOD"
    ) {

        communicationValue =
            0;

    } else if (
        communicationStatus === "OFFLINE"
    ) {

        communicationValue =
            1;
    }


    // --------------------------------------------------
    // GOOD / OFFLINE
    // --------------------------------------------------

    if (
        communicationValue !== null
    ) {

        const stateKey =
            `${deviceId}.BMS_Communication`;


        const hasPrevious =
            Object.prototype.hasOwnProperty.call(
                lastStates,
                stateKey
            );


        const changed =
            !hasPrevious ||
            lastStates[stateKey] !== communicationValue;


        if (
            changed
        ) {

            // ------------------------------------------
            // ACTUALIZAR CACHE
            // ------------------------------------------

            lastStates[stateKey] =
                communicationValue;

            cacheChanged =
                true;

            emittedCount++;


            // ------------------------------------------
            // SEVERIDAD
            // ------------------------------------------

            const severity =
                deviceConfig.health
                    ?.communicationAlarmSeverity ||
                "WARNING";


            // ------------------------------------------
            // ENVIAR TRANSICIÓN
            // ------------------------------------------

            node.send({

                healthAlarm:
                    true,

                device: {

                    id:
                        deviceId,

                    name:
                        deviceName,

                    gateway:
                        gatewayId
                },

                point:
                    "BMS_Communication",

                variable: {

                    name:
                        "Comunicación BMS",

                    type:
                        "bool",

                    unit:
                        "",

                    alarm:
                        true,

                    severity:
                        severity,

                    message:
                        "Supervisión de comunicación Modbus del equipo."
                },

                payload: {

                    value:
                        communicationValue
                }
            });
        }
    }


    // ==================================================
    // 6. HEARTBEAT / APLICACIÓN
    // ==================================================

    const application =
        deviceHealth.application || {};


    if (
        application.enabled === true
    ) {

        const applicationStatus =
            application.status ||
            "UNKNOWN";


        let applicationValue =
            null;


        if (
            applicationStatus === "GOOD"
        ) {

            applicationValue =
                0;

        } else if (
            applicationStatus === "BAD"
        ) {

            applicationValue =
                1;
        }


        // ----------------------------------------------
        // GOOD / BAD
        // ----------------------------------------------

        if (
            applicationValue !== null
        ) {

            const stateKey =
                `${deviceId}.BMS_ApplicationHeartbeat`;


            const hasPrevious =
                Object.prototype.hasOwnProperty.call(
                    lastStates,
                    stateKey
                );


            const changed =
                !hasPrevious ||
                lastStates[stateKey] !== applicationValue;


            if (
                changed
            ) {

                // --------------------------------------
                // ACTUALIZAR CACHE
                // --------------------------------------

                lastStates[stateKey] =
                    applicationValue;

                cacheChanged =
                    true;

                emittedCount++;


                // --------------------------------------
                // SEVERIDAD
                // --------------------------------------

                const severity =
                    deviceConfig.health
                        ?.applicationAlarmSeverity ||
                    "CRITICAL";


                // --------------------------------------
                // ENVIAR TRANSICIÓN
                // --------------------------------------

                node.send({

                    healthAlarm:
                        true,

                    device: {

                        id:
                            deviceId,

                        name:
                            deviceName,

                        gateway:
                            gatewayId
                    },

                    point:
                        "BMS_ApplicationHeartbeat",

                    variable: {

                        name:
                            "Heartbeat de aplicación",

                        type:
                            "bool",

                        unit:
                            "",

                        alarm:
                            true,

                        severity:
                            severity,

                        message:
                            "Supervisión de ejecución del programa mediante heartbeat."
                    },

                    payload: {

                        value:
                            applicationValue
                    }
                });
            }
        }
    }
}


// ======================================================
// 7. GUARDAR CACHE SÓLO SI HUBO CAMBIOS
// ======================================================
//
// Durante funcionamiento normal este bloque NO se
// ejecutará cada segundo.
//
// Sólo:
//
// - al arrancar
// - cuando un equipo cambia GOOD/OFFLINE
// - cuando un heartbeat cambia GOOD/BAD
//
// ======================================================

if (
    cacheChanged
) {

    global.set(
        "healthAlarmAdapterState",
        lastStates
    );


    // Sólo actualizamos status visual cuando realmente
    // ocurrió una transición.

    node.status({

        fill:
            "blue",

        shape:
            "dot",

        text:
            `HEALTH → ALARMS | ${emittedCount} cambio(s)`
    });
}


// ======================================================
// 8. FIN
// ======================================================

return null;

// ======================================================
// HEALTH MESSAGE PROJECTOR TEST
// ======================================================
//
// DIAGNÓSTICO TEMPORAL.
//
// OBJETIVO:
//
// Crear un mensaje NUEVO y mínimo para el Health Engine.
//
// El mensaje de adquisición original puede contener:
//
// - device completo
// - driver completo
// - todas las variables del driver
// - request Modbus
// - responseBuffer
// - parts
// - messageId
// - etc.
//
// Health / Heartbeat no necesita todo eso.
//
// ESTA VERSIÓN:
//
// - NO modifica el msg original
// - construye un objeto completamente nuevo
// - conserva únicamente lo necesario para Health
//
// NO ES TODAVÍA CÓDIGO DEFINITIVO DEL CORE.
// ======================================================


// ------------------------------------------------------
// VALIDACIONES BÁSICAS
// ------------------------------------------------------

if (
    !msg ||
    !msg.device ||
    !msg.device.id
) {
    return null;
}


if (
    typeof msg.point !== "string" ||
    msg.point.trim() === ""
) {
    return null;
}


// ------------------------------------------------------
// VALOR
// ------------------------------------------------------

const value =
    msg.payload?.value;


// ------------------------------------------------------
// HEALTH CONFIG DEL DEVICE
// ------------------------------------------------------

const sourceHealth =
    msg.device.health;


const projectedHealth =
    (
        sourceHealth &&
        typeof sourceHealth === "object"
    )
        ? {
            heartbeatPoint:
                sourceHealth.heartbeatPoint ?? null,

            heartbeatTimeoutMs:
                sourceHealth.heartbeatTimeoutMs ?? null
        }
        : {};


// ======================================================
// CONSTRUIR MENSAJE NUEVO
// ======================================================

const healthMsg = {

    _msgid:
        msg._msgid,

    point:
        msg.point,

    payload: {
        value: value
    },

    device: {

        id:
            msg.device.id,

        name:
            msg.device.name || msg.device.id,

        health:
            projectedHealth
    }
};


// ======================================================
// IMPORTANTE
// ======================================================
//
// NO copiamos:
//
// msg.parts
// msg._event
// msg.variable
// msg.messageId
// msg.modbusRequest
// msg.responseBuffer
// msg.topic
// msg.device.driver
// msg.device.gateway
//
// El objeto retornado es independiente del mensaje
// original de adquisición.
// ======================================================

return healthMsg;
